/* ============================================================
   12. MESSAGING
   ============================================================ */

/* Unified drawer surface */
.ps-msg-drawer {
  position: fixed;
  top: 70px;
  right: 0;
  bottom: 0;
  width: 850px;
  background: #0b1120;
  border-left: 1px solid rgba(148, 163, 184, 0.4);
  z-index: 1200;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: slideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Real mobile fix: 850px was more than double any real phone's viewport
   width - the dominant, confirmed cause of "not usable in the smaller
   phone UI." Full-viewport takeover on mobile, not a squeezed-down
   version of the same two-column layout, which wouldn't fit at any
   reasonable phone width regardless of scaling. */
@media (max-width: 768px) {
  .ps-msg-drawer { width: 100vw; top: 0; border-left: none; }

  /* List view is the default - hide the detail pane and its header
     segment until a message is actually selected or being composed. */
  .ps-msg-drawer:not(.ps-msg-drawer--detail-active) .ps-msg-content,
  .ps-msg-drawer:not(.ps-msg-drawer--detail-active) .ps-msg-topbar-right {
    display: none;
  }
  .ps-msg-drawer:not(.ps-msg-drawer--detail-active) .ps-msg-topbar-left {
    flex: 1;
  }

  /* Once a message is selected or composing starts, the detail pane
     takes over the full screen and the list/its header segment step
     aside - the same "list, then tap into detail" pattern every real
     mobile messaging app uses, not a squeezed two-column layout that
     was never going to fit at any phone width. */
  .ps-msg-drawer.ps-msg-drawer--detail-active .ps-msg-sidebar,
  .ps-msg-drawer.ps-msg-drawer--detail-active .ps-msg-topbar-left {
    display: none;
  }
  .ps-msg-drawer.ps-msg-drawer--detail-active .ps-msg-topbar-right {
    flex: 1;
  }

  .ps-msg-mobile-back { display: flex !important; }
}

/* Unified header bar spanning full width */
.ps-msg-topbar {
  display: flex;
  align-items: stretch;
  border-bottom: 1px solid rgba(51, 65, 85, 0.9);
  flex-shrink: 0;
  min-height: 64px;
  background: var(--ps-grad-header), #0b1120;
}

.ps-msg-topbar-left {
  width: 320px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  border-right: 1px solid rgba(51, 65, 85, 0.9);
}

.ps-msg-topbar-right {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  min-width: 0;
}

.ps-msg-title {
  font-size: 20px;
  font-weight: 800;
  color: #f1f5f9;
  letter-spacing: -0.3px;
  margin: 0;
}

/* Real, mobile-only "back to list" button - hidden by default (desktop
   never needs it, both panes are always visible there), only ever
   revealed by the mobile media query above once a message/compose is
   active. Same circular icon-button visual language as the existing
   close buttons, not a new, inconsistent shape. */
.ps-msg-mobile-back {
  display: none;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: none;
  border: none;
  color: #5a7299;
  cursor: pointer;
  flex-shrink: 0;
  margin-right: 8px;
  transition: background 0.15s, color 0.15s;
}
.ps-msg-mobile-back:hover { background: rgba(255,255,255,0.06); color: #64748b; }

.ps-msg-title-row { display: flex; align-items: center; gap: 10px; }
.ps-msg-header-actions { display: flex; align-items: center; gap: 4px; }

.ps-msg-edit-btn {
  color: #0A84FF;
  background: none;
  border: none;
  font-size: 14px;
  cursor: pointer;
  font-weight: 600;
  padding: 4px 8px;
  border-radius: 6px;
  transition: background 0.15s;
}
.ps-msg-edit-btn:hover { background: rgba(10,132,255,0.1); }

.ps-msg-filter-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: #94a3b8;
  display: flex;
  align-items: center;
  padding: 4px;
  border-radius: 6px;
  transition: background 0.15s, color 0.15s;
}
.ps-msg-filter-btn:hover { color: #94a3b8; background: rgba(255,255,255,0.06); }

.ps-msg-filter-wrap { position: relative; }
.ps-msg-filter-backdrop { position: fixed; inset: 0; z-index: 999; }
.ps-msg-filter-menu {
  position: absolute;
  top: 35px;
  right: 0;
  width: 190px;
  background: #1a1d2a;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,0.1);
  z-index: 1000;
  padding: 4px;
}
.ps-msg-filter-item {
  padding: 12px 16px;
  font-size: 14px;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  border-radius: 8px;
  color: #e2e8f0;
  transition: background 0.15s;
}
.ps-msg-filter-item:hover { background: rgba(255,255,255,0.05); }
.ps-msg-filter-item--active { color: #0891B2; }
.ps-msg-filter-check { color: #0891B2; }

/* Real, shared close-button class - this exact combination of styles was
   duplicated three separate times inline (thread view, compose view,
   empty state), each with its own copy of the same JS hover handlers.
   One real class, one real :hover rule. */
.ps-msg-close-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: #5a7299;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  flex-shrink: 0;
  transition: color 0.15s, background 0.15s;
}
.ps-msg-close-btn:hover { color: #64748b; background: rgba(255,255,255,0.06); }
.ps-msg-close-btn--empty { margin-left: auto; }
.ps-msg-close-btn--thread { margin-left: 12px; }

.ps-msg-thread-header { flex: 1; min-width: 0; }
.ps-msg-thread-name-row { display: flex; align-items: center; gap: 8px; margin-bottom: 2px; }
.ps-msg-thread-name { font-size: 16px; font-weight: 700; color: #f1f5f9; letter-spacing: -0.2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ps-msg-urgent-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
  background: rgba(255,69,58,0.12);
  color: #FF453A;
  border: 1px solid rgba(255,69,58,0.25);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  flex-shrink: 0;
}
.ps-msg-thread-meta-row { display: flex; align-items: center; gap: 8px; }
.ps-msg-thread-subject { font-size: 12px; color: #6b7f99; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.ps-msg-case-link {
  background: rgba(8,145,178,0.08);
  border: 1px solid rgba(8,145,178,0.2);
  border-radius: 5px;
  cursor: pointer;
  color: #0891B2;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  transition: background 0.15s;
}
.ps-msg-case-link:hover { background: rgba(8,145,178,0.15); }

.ps-msg-config-link {
  background: rgba(99,102,241,0.08);
  border: 1px solid rgba(99,102,241,0.25);
  border-radius: 5px;
  cursor: pointer;
  color: #818cf8;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  transition: background 0.15s;
}
.ps-msg-config-link:hover { background: rgba(99,102,241,0.18); }

.ps-msg-compose-title { font-size: 15px; font-weight: 600; color: #0891B2; }

.ps-msg-empty-state { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; color: #8aaccc; }
.ps-msg-empty-icon { opacity: 0.35; }
.ps-msg-empty-text { font-size: 13px; margin: 0; }

/* Body row */
.ps-msg-body {
  flex: 1;
  display: flex;
  overflow: hidden;
  min-height: 0;
}

/* Left sidebar */
/* Real fix (PS-97/PS-96): this used to lose the cascade to a second,
   dead .ps-msg-sidebar definition pasted in from an abandoned earlier
   Messages UI spec further down this file (300px, var-based, missing
   flex-shrink: 0 — the actual cause of the Message Drawer's visible
   misalignment). That dead rule has been renamed to
   .ps-msg-legacy-sidebar (unused by any component) so this, the one
   real ps-msg-sidebar the live Message Drawer (AppShell.tsx) actually
   uses, now applies uncontested. PS-78 (Batch 319) then deleted that
   renamed rule with the rest of the dead ps-msg-* block. */
.ps-msg-sidebar {
  width: 320px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: var(--ps-grad-left), var(--ps-navy-left);
  border-right: 1px solid rgba(30, 41, 59, 0.9);
  overflow: hidden;
}

/* Right content pane */
.ps-msg-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--ps-grad-right), var(--ps-navy-right);
  overflow: hidden;
  min-width: 0;
  pointer-events: all;
}


/* Sidebar footer */
.ps-msg-sidebar-footer {
  padding: 14px 18px 34px;
  border-top: 1px solid rgba(51, 65, 85, 0.9);
  background: var(--ps-navy-left);
  flex-shrink: 0;
}

.ps-msg-list-status { padding: 40px 20px; text-align: center; color: #6b8099; font-size: 14px; }

.ps-msg-row-hover-actions { display: flex; gap: 8px; }
.ps-msg-row-restore-btn { background: none; border: none; cursor: pointer; color: #0891B2; font-size: 11px; font-weight: 600; padding: 0; }
.ps-msg-row-delete-link { background: none; border: none; cursor: pointer; color: #EF4444; font-size: 11px; font-weight: 600; padding: 0; }
.ps-msg-row-delete-icon-btn { background: none; border: none; cursor: pointer; color: #EF4444; display: flex; align-items: center; padding: 0; }

.ps-msg-footer-edit-row { display: flex; justify-content: space-between; align-items: center; }
.ps-msg-footer-readall-btn { background: none; border: none; color: #0891B2; cursor: pointer; font-size: 14px; padding: 0; }
.ps-msg-footer-deleteall-btn { background: none; border: none; cursor: pointer; color: #EF4444; font-size: 14px; font-weight: 600; padding: 0; }
.ps-msg-footer-deleteall-btn:disabled { cursor: default; color: #94a3b8; }
.ps-msg-footer-deleteall-btn--centered { display: block; margin: 0 auto; }
.ps-msg-footer-empty-row { display: flex; justify-content: center; }
.ps-msg-footer-normal-row { display: flex; align-items: center; gap: 8px; }
.ps-msg-footer-normal-row .ps-msg-search { flex: 1; min-width: 0; }

.ps-msg-compose-icon-btn { background: none; border: none; cursor: pointer; color: #0891B2; display: flex; align-items: center; padding: 5px; border-radius: 6px; transition: background 0.15s; }
.ps-msg-compose-icon-btn:hover:not(:disabled) { background: rgba(8,145,178,0.12); }
.ps-msg-compose-icon-btn:disabled { cursor: default; color: #334d66; }

.ps-msg-footer-secure-btn { background: none; border: 1px solid rgba(100,130,160,0.35); cursor: pointer; color: #7a95b0; display: flex; align-items: center; padding: 4px 7px; border-radius: 6px; gap: 4px; transition: color 0.15s, border-color 0.15s; font-size: 10px; font-weight: 700; }
.ps-msg-footer-secure-btn:hover { color: #38bdf8; border-color: rgba(56,189,248,0.3); }

/* Thread area */
.ps-msg-thread {
  flex: 1;
  padding: 24px 32px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
