}

.ps-send-btn.active:hover { background: #0e7490; }

/* Thread sender header (within topbar right) */
.ps-thread-sender {
  font-size: 16px;
  font-weight: 700;
  color: #f1f5f9;
  letter-spacing: -0.2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ps-thread-subject {
  font-size: 12px;
