/* ============================================================
   COMPUTATIONAL FLAG ICON — worklist circular test-panel icon
   ps-comp-flag-btn: the clickable button (border/bg set inline)
   ps-comp-flag-dot: status dot pinned to bottom-right corner
   ps-pulse-subtle:  keyframe for PRELIMINARY state heartbeat
   ============================================================ */

.ps-comp-flag-btn {
  /* Layout */
  display:         inline-flex;
  align-items:     center;
  justify-content: center;
  flex-direction:  column;
  flex-shrink:     0;
  /* Shape — width/height set via inline style by component */
  border-radius:   7px;
  padding:         0;
  position:        relative;
  /* Interaction */
  cursor:          pointer;
  outline:         none;
  /* Animation */
  transition:      transform 0.15s ease, box-shadow 0.15s ease, opacity 0.15s;
}

.ps-comp-flag-btn:hover {
  transform:  translateY(-1px);
  box-shadow: 0 3px 8px rgba(0,0,0,0.4);
  opacity:    0.9;
}

.ps-comp-flag-btn:active {
  transform: translateY(0);
}

.ps-comp-flag-btn:focus-visible {
  outline:        2px solid #38bdf8;
  outline-offset: 2px;
}

/* Status dot — bottom-right corner of the icon */
.ps-comp-flag-dot {
  position:      absolute;
  bottom:        -3px;
  right:         -3px;
  width:         8px;
  height:        8px;
  border-radius: 50%;
  /* background set inline by component */
  /* Hairline ring to separate dot from whatever is behind it */
  box-shadow:    0 0 0 1.5px #0d1829;
  flex-shrink:   0;
}

/* Preliminary pulse — gentle opacity / glow heartbeat */
@keyframes ps-pulse-subtle {
  0%,  100% { opacity: 1;    box-shadow: 0 0 0 1.5px #0d1829; }
  50%       { opacity: 0.75; box-shadow: 0 0 0 1.5px #0d1829, 0 0 8px 2px rgba(186,117,23,0.4); }
}


