.ps-prefin-preview-content    { display: flex; flex-direction: column; gap: 16px; }

.ps-prefin-preview-report        { border-radius: 8px; border: 1px solid #334155; overflow: hidden; background: #1e293b; }
.ps-prefin-preview-report-header { display: flex; align-items: center; gap: 10px; padding: 10px 14px; background: rgba(255,255,255,0.03); border-bottom: 1px solid #334155; }
.ps-prefin-preview-specimen-badge { font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 5px; background: rgba(8,145,178,0.15); color: #38bdf8; border: 1px solid rgba(8,145,178,0.3); flex-shrink: 0; }
