.ps-ai-review-confidence     { font-size: 11px; font-weight: 800; padding: 1px 8px; border-radius: 20px; border: 1px solid var(--ps-ai-review-conf-border); color: var(--ps-ai-review-conf-color); background: var(--ps-ai-review-conf-bg); }
.ps-ai-review-confidence--high   { --ps-ai-review-conf-color: #34d399; --ps-ai-review-conf-bg: #34d39922; --ps-ai-review-conf-border: #34d39944; }
