/* ── CSS Custom Property colour system ───────────────────────────────────────
   PathScribe uses data-driven colours for flags, delegation types, synoptic
   sections, etc. Instead of 3–5 inline style props per element, components
   set a single custom property and all colour expressions live in CSS.

   Usage in JSX:
     <div className="ps-hue-card" style={{ '--ps-hue': entity.color } as React.CSSProperties}>

   Replaces patterns like:
     style={{ background: color+'18', color: color, border: `1px solid ${color}44` }}
──────────────────────────────────────────────────────────────────────────────── */

/* Entity colour card / badge — uses --ps-hue custom property */
.ps-hue-card {
  background: color-mix(in srgb, var(--ps-hue, #0891B2) 10%, transparent);
  color:      var(--ps-hue, #0891B2);
  border:     1px solid color-mix(in srgb, var(--ps-hue, #0891B2) 28%, transparent);
  border-radius: 8px;
}

/* Inline badge / chip variant */
.ps-hue-badge {
  background: color-mix(in srgb, var(--ps-hue, #0891B2) 13%, transparent);
  color:      var(--ps-hue, #0891B2);
  border:     1px solid color-mix(in srgb, var(--ps-hue, #0891B2) 26%, transparent);
  font-size:  11px;
  font-weight: 700;
  padding:    2px 8px;
  border-radius: 10px;
}

/* Avatar / dot variant */
.ps-hue-avatar {
  background: color-mix(in srgb, var(--ps-hue, #0891B2) 20%, transparent);
  color:      var(--ps-hue, #0891B2);
  border:     1px solid color-mix(in srgb, var(--ps-hue, #0891B2) 35%, transparent);
  border-radius: 50%;
  display:    flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

/* Selected row state */
.ps-hue-row-selected {
  background: color-mix(in srgb, var(--ps-hue, #0891B2) 8%, transparent);
  border-color: color-mix(in srgb, var(--ps-hue, #0891B2) 40%, transparent);
}

/* Accent text — colour only, no background */
.ps-hue-text { color: var(--ps-hue, #0891B2); }

/* Dot indicator — e.g. flag/status dot */
.ps-hue-dot {
  background:    var(--ps-hue, #0891B2);
  border-radius: 50%;
  flex-shrink:   0;
}

