/* overlay — already exists as .ps-overlay, this adds the modalStyles variant */
.ps-ms-overlay {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  background-color: rgba(0,0,0,0.6);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 9000;
  /* Real fix, per direct report: modals "seem a little elevated
   * which seems to hide the top border." Confirmed live at a
   * realistic laptop-height viewport before this fix. Same
   * NavBar-clearing convention already proven in .ps-conf-backdrop. */
  padding-top: 88px;
  padding-bottom: 32px;
  box-sizing: border-box;
  overflow-y: auto;
}

.ps-ms-modal {
  background-color: #111827;
  border-radius: 8px;
  border: 1px solid #1f2933;
  max-height: 95vh;
  width: 520px;
  max-width: 90vw;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Helvetica', 'Arial', sans-serif;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: 0 18px 45px rgba(0,0,0,0.7);
}

.ps-ms-header {
  font-size: 18px;
  font-weight: 600;
  color: #e5e7eb;
  margin-bottom: 4px;
}

.ps-ms-subheader {
  font-size: 13px;
  color: #9ca3af;
  margin-bottom: 4px;
}

.ps-ms-field-group {
  display: flex;
  flex-direction: column;
  margin-bottom: 12px;
}

.ps-ms-label {
  font-size: 12px;
  font-weight: 500;
  color: #9ca3af;
  margin-bottom: 4px;
  display: block;
}

.ps-ms-input,
.ps-ms-textarea,
.ps-ms-select {
  width: 100%;
  padding: 8px 10px;
  border-radius: 6px;
  border: 1px solid #374151;
  background-color: #020617;
  color: #e5e7eb;
  font-size: 14px;
  outline: none;
  box-sizing: border-box;
  font-family: inherit;
}

.ps-ms-textarea {
  min-height: 90px;
  resize: vertical;
}

.ps-ms-select {
  appearance: none;
}

.ps-ms-footer {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 8px;
}

.ps-ms-btn-cancel {
