.ps-sub-tab-count--empty     { background: #1a1a1a; color: #94a3b8; border: 1px solid #2a2a2a; }
.ps-sub-tab-content          { background: #0d0d0d; flex: 1; min-height: 0; display: flex; flex-direction: column; }

.ps-sub-tab-search           { padding: 10px 10px 4px; flex-shrink: 0; }
.ps-sub-tab-list             { flex: 1; overflow-y: auto; padding: 4px 10px 10px; }

