/* Check row */
.ps-sub-check-row            { display: flex; align-items: center; gap: 12px; padding: 9px 12px; border-radius: 7px; cursor: pointer; margin-bottom: 2px; border: 1px solid transparent; transition: all 0.15s; }

.ps-sub-check-row--checked   { background: rgba(34,197,94,0.06); border-color: rgba(34,197,94,0.2); }
.ps-sub-check-row--unchecked { background: transparent; }

.ps-sub-check-box            { width: 16px; height: 16px; border-radius: 4px; flex-shrink: 0; display: flex; align-items: center; justify-content: center; transition: all 0.15s; }
.ps-sub-check-box--checked   { border: 2px solid #22c55e; background: #22c55e; }

.ps-sub-check-box--unchecked { border: 2px solid #374151; background: transparent; }
.ps-sub-check-tick           { color: #fff; font-size: 10px; font-weight: 900; }

.ps-sub-check-label          { font-size: 13px; color: #f9fafb; font-weight: 500; }
.ps-sub-check-sub            { font-size: 11px; color: #94a3b8; margin-top: 1px; }

.ps-sub-search-wrap          { position: relative; margin-bottom: 8px; }
