  flex-shrink: 0;
}

.ps-ms-btn-cancel {
  padding: 8px 14px;
  border-radius: 6px;
  border: 1px solid #4b5563;
  background-color: #111827;
  color: #e5e7eb;
  font-size: 14px;
  cursor: pointer;
  font-family: inherit;
  transition: all 0.15s;
}

.ps-ms-btn-apply {
  padding: 8px 14px;
  border-radius: 6px;
  border: none;
  background-color: #2563eb;
  color: #ffffff;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  transition: background-color 0.15s;
}
.ps-ms-btn-apply:hover {
  background-color: #1d4ed8;
}


.ps-conf-select:focus {
  border-color: #0891B2;
  outline: none;
}


