.ps-tat-hierarchy-box      { background: rgba(138,180,248,0.04); border: 1px solid rgba(138,180,248,0.12); border-radius: 10px; padding: 14px 16px; }
.ps-tat-hierarchy-list     { display: flex; flex-wrap: wrap; gap: 8px; }
