/* ── Field jump highlight — pulses when jumped to from Cannot Finalise ─────── */
.ps-field-jump-highlight {
  outline: 2px solid #38bdf8 !important;
  outline-offset: 3px;
  animation: ps-field-jump-pulse 2s ease-out forwards;
}
@keyframes ps-field-jump-pulse {
  0%   { outline-color: #38bdf8; box-shadow: 0 0 0 4px rgba(56,189,248,0.3); }
  60%  { outline-color: #38bdf8; box-shadow: 0 0 0 4px rgba(56,189,248,0.1); }
  100% { outline-color: transparent; box-shadow: none; }
}

