.ps-orch2-edit-syn-btn     { font-size: 10px; color: #0891B2; background: none; border: none; cursor: pointer; font-family: inherit; }
.ps-orch2-edit-syn-btn:hover { text-decoration: underline; }

/* Streaming block */
.ps-orch2-streaming-block  { min-height: 80px; background: #f0f9ff; border: 1px solid #bae6fd; border-radius: 6px; padding: 12px 14px; font-size: 13px; line-height: 1.8; color: #1f2937; font-family: 'Georgia','Times New Roman',serif; white-space: pre-wrap; word-break: break-word; }
.ps-orch2-cursor           { display: inline-block; width: 2px; height: 1em; background: #0891B2; margin-left: 2px; vertical-align: text-bottom; animation: ps-orch2-cursor 0.9s ease-in-out infinite; }

/* ── OrchestratorReportPanel v3 — single editor ─────────────────────────── */
@keyframes ps-orch3-pulse { 0%,100%{opacity:1} 50%{opacity:0.2} }

.ps-orch3-shell             { display: flex; flex-direction: column; height: 100%; overflow: hidden; background: #1a2234; }

/* ═══════════════════════════════════════════════════════════════════════════
   ps-orch4-*  —  OrchestratorReportPanel v4 (navigator + sticky toolbar)
   Add after existing ps-orch3-* block in pathscribe.css
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── Shell: full-height flex row ─────────────────────────────────────────── */
.ps-orch4-shell {
  display: flex;
  flex-direction: row;
  height: 100%;
  width: 100%;
  overflow: hidden;
  background: #0f172a;
}

/* ── Section Navigator ───────────────────────────────────────────────────── */
.ps-orch4-nav {
  width: 220px;
  min-width: 220px;
  max-width: 220px;
  display: flex;
  flex-direction: column;
  background: #0d1829;
  border-right: 1px solid rgba(148, 163, 184, 0.1);
  overflow: hidden;
}

.ps-orch4-nav-header {
  padding: 14px 16px 8px;
  flex-shrink: 0;
}

.ps-orch4-nav-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #0891b2;
  text-transform: uppercase;
}

.ps-orch4-nav-legend {
  padding: 4px 16px 8px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex-shrink: 0;
}

.ps-orch4-nav-legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  color: #94a3b8;
}

.ps-orch4-nav-divider {
  height: 1px;
  background: rgba(148, 163, 184, 0.08);
  margin: 0 16px 8px;
  flex-shrink: 0;
}

.ps-orch4-nav-list {
  list-style: none;
  margin: 0;
  padding: 0 8px;
  flex: 1;
  overflow-y: auto;
}

.ps-orch4-nav-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 10px;
  border: none;
  border-radius: 6px;
  background: transparent;
  cursor: pointer;
  text-align: left;
  transition: background 0.15s;
  margin-bottom: 2px;
}

.ps-orch4-nav-item:hover {
  background: rgba(8, 145, 178, 0.08);
}

.ps-orch4-nav-item--active {
  background: rgba(8, 145, 178, 0.15);
  border-left: 3px solid #0891b2;
  padding-left: 7px;
}

.ps-orch4-nav-num {
  font-size: 10px;
  font-weight: 700;
  color: #94a3b8;
  min-width: 16px;
  flex-shrink: 0;
}

.ps-orch4-nav-item--active .ps-orch4-nav-num {
  color: #38bdf8;
}

.ps-orch4-nav-label {
  font-size: 12px;
  color: #cbd5e1;
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.ps-orch4-nav-item--active .ps-orch4-nav-label {
  color: #e2e8f0;
  font-weight: 600;
}

.ps-orch4-nav-dot {
  font-size: 12px;
  flex-shrink: 0;
  line-height: 1;
}

.ps-orch4-nav-lock {
  font-size: 9px;
  opacity: 0.5;
  flex-shrink: 0;
  line-height: 1;
}

.ps-orch4-nav-streaming {
  font-size: 11px;
  color: #0891b2;
  animation: ps-orch4-spin 1s linear infinite;
  flex-shrink: 0;
}

@keyframes ps-orch4-spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

.ps-orch4-nav-footer {
  padding: 10px 16px 14px;
  border-top: 1px solid rgba(148, 163, 184, 0.08);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ps-orch4-nav-gen-status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #38bdf8;
}

.ps-orch4-nav-gen-time {
  font-size: 10px;
  color: #94a3b8;
}

.ps-orch4-nav-edited {
  font-size: 10px;
  color: #a78bfa;
}

/* ── Pulse dot ───────────────────────────────────────────────────────────── */
.ps-orch4-dot-pulse {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #38bdf8;
  animation: ps-orch4-pulse 1.2s ease-in-out infinite;
}

@keyframes ps-orch4-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.4; transform: scale(0.75); }
}

/* ── Main column (toolbar + canvas) ─────────────────────────────────────── */
.ps-orch4-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-width: 0;
}

/* ── Sticky Toolbar ──────────────────────────────────────────────────────── */
.ps-orch4-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 14px;
  background: #1e293b;
  border-bottom: 1px solid rgba(148, 163, 184, 0.12);
  flex-shrink: 0;
  flex-wrap: wrap;
  position: sticky;
  top: 0;
  z-index: 20;
}

.ps-orch4-toolbar-left,
.ps-orch4-toolbar-right {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: nowrap;
  flex-shrink: 0;
}

.ps-orch4-toolbar-right {
  padding: 0 10px;
  border-left: 1px solid rgba(148,163,184,0.12);
  margin-left: auto;
}

.ps-orch4-tb-select {
  padding: 3px 6px;
  background: #0f172a;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 4px;
  color: #e2e8f0;
  font-size: 12px;
  cursor: pointer;
}

.ps-orch4-tb-font { width: 110px; }
.ps-orch4-tb-size { width: 52px; }

.ps-orch4-tb-divider {
  width: 1px;
  height: 20px;
  background: rgba(148, 163, 184, 0.15);
  margin: 0 4px;
  flex-shrink: 0;
}

.ps-orch4-tb-btn {
  padding: 3px 8px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 4px;
  color: #cbd5e1;
  font-size: 13px;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s;
  line-height: 1.4;
}

.ps-orch4-tb-btn:hover {
  background: rgba(148, 163, 184, 0.1);
  border-color: rgba(148, 163, 184, 0.2);
}

.ps-orch4-tb-btn--italic  { font-style: italic; }
.ps-orch4-tb-btn--underline { text-decoration: underline; }

.ps-orch4-tb-regen {
  color: #38bdf8;
  border-color: rgba(56, 189, 248, 0.25);
}

/* Track changes toggle */
.ps-orch4-tb-track {
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}

.ps-orch4-tb-track-label {
  font-size: 11px;
  color: #64748b;
  user-select: none;
}

.ps-orch4-tb-track-toggle {
  display: inline-block;
  width: 30px;
  height: 16px;
  background: rgba(8, 145, 178, 0.4);
  border-radius: 8px;
  position: relative;
}

.ps-orch4-tb-track-toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  background: #38bdf8;
  border-radius: 50%;
  transition: left 0.15s;
}

/* Template indicator in toolbar */
.ps-orch4-tb-tmpl {
  display: flex;
  align-items: center;
  gap: 6px;
  position: relative;
}

.ps-orch4-tb-tmpl-name {
  font-size: 11px;
  color: #e2e8f0;
  font-weight: 600;
  max-width: 200px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ps-orch4-tb-tmpl-by {
  font-size: 10px;
  color: #94a3b8;
  white-space: nowrap;
}

.ps-orch4-tb-tmpl-change {
  padding: 2px 8px;
  background: transparent;
  border: 1px solid rgba(148, 163, 184, 0.25);
  border-radius: 4px;
  color: #94a3b8;
  font-size: 11px;
  cursor: pointer;
  transition: all 0.12s;
}

.ps-orch4-tb-tmpl-change:hover {
  background: rgba(148, 163, 184, 0.1);
  color: #e2e8f0;
}

.ps-orch4-tb-tmpl-reset {
  padding: 2px 8px;
  background: transparent;
  border: 1px solid rgba(56, 189, 248, 0.3);
  border-radius: 4px;
  color: #38bdf8;
  font-size: 11px;
  cursor: pointer;
}

.ps-orch4-tmpl-change-wrap { position: relative; }

.ps-orch4-tmpl-picker {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  width: 280px;
  background: #1e293b;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 8px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  z-index: 100;
  padding: 8px 0;
}

.ps-orch4-tmpl-picker-title {
  font-size: 11px;
  font-weight: 700;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 4px 14px 8px;
}

.ps-orch4-tmpl-picker-warn {
  font-size: 11px;
  color: #fbbf24;
  background: rgba(245, 158, 11, 0.08);
  border-top: 1px solid rgba(245, 158, 11, 0.2);
  border-bottom: 1px solid rgba(245, 158, 11, 0.2);
  padding: 6px 14px;
  margin-bottom: 4px;
}

.ps-orch4-tmpl-option {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 14px;
  cursor: pointer;
  transition: background 0.1s;
}

.ps-orch4-tmpl-option:hover { background: rgba(8, 145, 178, 0.1); }

.ps-orch4-tmpl-option--active { background: rgba(8, 145, 178, 0.15); }

.ps-orch4-tmpl-option-name {
  font-size: 12px;
  color: #e2e8f0;
  font-weight: 500;
}

.ps-orch4-tmpl-option-meta {
  font-size: 10px;
  color: #64748b;
}

/* Action buttons (Print / Export PDF) */
.ps-orch4-tb-action {
  padding: 5px 12px;
  background: rgba(148, 163, 184, 0.08);
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 5px;
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s;
  white-space: nowrap;
}

.ps-orch4-tb-action:hover {
  background: rgba(148, 163, 184, 0.15);
  border-color: rgba(148, 163, 184, 0.35);
}

.ps-orch4-tb-action--primary {
  background: rgba(8, 145, 178, 0.15);
  border-color: rgba(8, 145, 178, 0.4);
  color: #38bdf8;
}

.ps-orch4-tb-action--primary:hover {
  background: rgba(8, 145, 178, 0.25);
  border-color: #0891b2;
}

/* ── Pending draft banner ─────────────────────────────────────────────────── */
.ps-orch4-pending-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 16px;
  background: rgba(245, 158, 11, 0.08);
  border-bottom: 1px solid rgba(245, 158, 11, 0.2);
  flex-shrink: 0;
  flex-wrap: wrap;
}

.ps-orch4-pending-label {
  font-size: 12px;
  font-weight: 600;
  color: #fbbf24;
}

.ps-orch4-pending-btns {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.ps-orch4-btn-replace {
  padding: 4px 12px;
  background: rgba(8, 145, 178, 0.15);
  border: 1px solid rgba(8, 145, 178, 0.4);
  border-radius: 5px;
  color: #38bdf8;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.ps-orch4-btn-keep {
  padding: 4px 12px;
  background: rgba(148, 163, 184, 0.06);
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 5px;
  color: #94a3b8;
  font-size: 12px;
  cursor: pointer;
}

/* ── Scrollable canvas ───────────────────────────────────────────────────── */
.ps-orch4-canvas-wrap {
  flex: 1;
  overflow-y: auto;
  background: #1a2332;
  padding: 28px 32px 60px;
}

/* White page */
.ps-orch4-page {
  max-width: 860px;
  margin: 0 auto;
  background: #ffffff;
  border-radius: 4px;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.35);
  overflow: hidden;
}

/* ── Protected header ────────────────────────────────────────────────────── */
.ps-orch4-protected-header {
  padding: 20px 32px 16px;
  background: #f8fafc;
  border-bottom: 2px solid #e2e8f0;
  position: relative;
}

.ps-orch4-protected-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 10px;
  background: rgba(148, 163, 184, 0.1);
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 4px;
  padding: 2px 8px;
}

.ps-orch4-lock-icon {
  font-size: 10px;
  opacity: 0.7;
}

.ps-orch4-ph-accession {
  font-size: 22px;
  font-weight: 700;
  color: #e2e8f0;
  letter-spacing: -0.01em;
  margin-bottom: 10px;
  font-family: 'Georgia', serif;
}

.ps-orch4-ph-grid {
  display: grid;
  grid-template-columns: 90px 1fr;
  gap: 4px 12px;
  max-width: 420px;
}

.ps-orch4-ph-key {
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding-top: 1px;
}

.ps-orch4-ph-val {
  font-size: 13px;
  color: #94a3b8;
  font-weight: 500;
}

.ps-orch4-ph-rule {
  height: 1px;
  background: #e2e8f0;
  margin-top: 14px;
}

/* ── Editor body ─────────────────────────────────────────────────────────── */
.ps-orch4-editor-body {
  padding: 24px 32px 40px;
}

/* Section anchor headings rendered inside the editor */
.ps-orch4-anchor {
  font-size: 14px;
  font-weight: 700;
  color: #0f172a;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-left: 3px solid #0891b2;
  padding: 10px 0 10px 12px;
  margin: 28px 0 10px;
  user-select: none;
  pointer-events: none;
  background: transparent;
  /* Sticky within canvas scroll */
  position: sticky;
  top: 0;
  z-index: 5;
  background: #ffffff;
}

/* ── Empty state ─────────────────────────────────────────────────────────── */
.ps-orch4-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 48px 32px;
  text-align: center;
  gap: 12px;
}

.ps-orch4-empty-icon  { font-size: 40px; }
.ps-orch4-empty-title { font-size: 18px; font-weight: 700; color: #e2e8f0; }
.ps-orch4-empty-body  { font-size: 14px; color: #94a3b8; max-width: 380px; line-height: 1.6; }
.ps-orch4-empty-hint  { font-size: 12px; color: #94a3b8; max-width: 340px; line-height: 1.5; }
.ps-orch4-empty-cta   { color: #38bdf8; font-weight: 600; }

/* ══════════════════════════════════════════════════════════════════════════
   Print styles — report body only, no chrome
   ══════════════════════════════════════════════════════════════════════════ */
@media print {
  /* Hide everything */
  /* Real fix, per direct report with screenshot in hand: "On print,
     just gave a blank case." Confirmed directly: this rule (built for
     the Orchestrator report print view) hides the ENTIRE app root on
     print, since the root itself is never .ps-orch4-shell — a real,
     genuine bug for any OTHER print feature in this app that doesn't
     live inside that specific shell, including MaterialTrackingHistory
     Modal.tsx's own print button, no matter how correct its own print
     CSS is (display:none on an ancestor can never be undone by a
     descendant). .ps-mth-overlay (portaled directly to document.body,
     same real pattern the Dev Tools dropdown fix already used) is now
     also exempted here. */
  body > *:not(.ps-orch4-shell):not(.ps-mth-overlay):not(.ps-cyto-histo-print-overlay) { display: none !important; }

  /* Hide nav chrome */
  .ps-orch4-nav,
  .ps-orch4-toolbar,
  .ps-orch4-pending-bar,
  .ps-orch4-protected-badge { display: none !important; }

  /* Let canvas expand */
  .ps-orch4-shell,
  .ps-orch4-main,
  .ps-orch4-canvas-wrap { overflow: visible !important; height: auto !important; }

  /* Page fills print area */
  .ps-orch4-page {
    box-shadow: none !important;
    border-radius: 0 !important;
    max-width: 100% !important;
  }

  /* Protected header prints as-is but badge hides */
  .ps-orch4-protected-header { background: white !important; border-bottom: 1px solid #ccc !important; }

  /* Anchors print as static headers */
  .ps-orch4-anchor { position: static !important; }
}


/* Empty state */
