.ps-orch3-empty-icon        { font-size: 36px; margin-bottom: 14px; opacity: 0.2; }
.ps-orch3-empty-title       { font-size: 14px; font-weight: 700; color: #e2e8f0; margin-bottom: 10px; }
.ps-orch3-empty-body        { font-size: 12px; color: #94a3b8; max-width: 300px; line-height: 1.75; }
.ps-orch3-empty-cta         { color: #38bdf8; font-weight: 600; }
.ps-orch3-empty-hint        { margin-top: 14px; font-size: 11px; color: #94a3b8; line-height: 1.7; max-width: 280px; }

