.ps-orch3-gen-label         { font-size: 11px; color: #38bdf8; font-weight: 600; }
.ps-orch3-gen-time          { font-size: 11px; color: #94a3b8; }
.ps-orch3-edited-pill       { font-size: 10px; color: #94a3b8; background: rgba(255,255,255,0.05); padding: 2px 8px; border-radius: 99px; }
.ps-orch3-regen-all-btn     { font-size: 11px; color: #94a3b8; background: none; border: 1px solid rgba(255,255,255,0.08); border-radius: 5px; padding: 3px 10px; cursor: pointer; font-family: inherit; transition: color 0.15s; }
.ps-orch3-regen-all-btn:hover { color: #0891B2; border-color: rgba(8,145,178,0.3); }

/* Pending banner */
