.ps-orch3-btn-keep          { font-size: 10px; color: #94a3b8; background: white; border: 1px solid #d1d5db; border-radius: 3px; padding: 2px 8px; cursor: pointer; font-family: inherit; }

/* White canvas */
.ps-orch3-canvas-wrap       { flex: 1; overflow-y: auto; background: #1a2234; padding: 16px 20px; }
.ps-orch3-doc               { background: #ffffff; border-radius: 4px; box-shadow: 0 2px 20px rgba(0,0,0,0.4), 0 0 0 1px rgba(0,0,0,0.15); padding: 40px 48px; min-height: 100%; }

/* Letterhead */
.ps-orch3-letterhead        { margin-bottom: 24px; }
.ps-orch3-lh-acc            { font-size: 20px; font-weight: 700; color: #e2e8f0; letter-spacing: 1px; font-family: 'Georgia','Times New Roman',serif; margin-bottom: 6px; }
.ps-orch3-lh-fields         { display: flex; flex-wrap: wrap; gap: 4px 20px; margin-bottom: 12px; }
.ps-orch3-lh-key            { font-size: 10px; font-weight: 700; color: #0891B2; text-transform: uppercase; letter-spacing: 0.06em; margin-right: 4px; }
