}

/* ── RoutingRulesTab ─────────────────────────────────────────────────────── */
.ps-rr-root             { display: flex; flex-direction: column; height: 100%; }
.ps-rr-header           { margin-bottom: 20px; }
.ps-rr-layout           { display: grid; grid-template-columns: 1fr 340px; gap: 24px; flex: 1; min-height: 0; overflow: hidden; }
.ps-rr-tables           { overflow-y: auto; display: flex; flex-direction: column; gap: 20px; }

/* Priority chain */
.ps-rr-priority         { background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.06); border-radius: 8px; padding: 12px 16px; }
.ps-rr-priority-title   { font-size: 10px; font-weight: 700; color: #9aa7bb; text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 8px; }
.ps-rr-priority-row     { display: flex; align-items: center; gap: 10px; padding: 3px 0; }
.ps-rr-priority-pass    { font-size: 11px; font-weight: 700; width: 50px; flex-shrink: 0; }
.ps-rr-priority-label   { font-size: 12px; color: #94a3b8; flex: 0 0 150px; flex-shrink: 0; }
.ps-rr-priority-result  { font-size: 11.5px; color: #aab4c4; flex: 1; overflow: hidden;
  text-overflow: ellipsis; white-space: nowrap; }
.ps-rr-priority-admin   { font-size: 10px; color: #8b98ac; font-style: italic; flex-shrink: 0; }

/* Section */
.ps-rr-section          { background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.06); border-radius: 8px; overflow: hidden; }
.ps-rr-section-header   { display: flex; align-items: center; gap: 10px; padding: 12px 16px; border-bottom: 1px solid rgba(255,255,255,0.06); }
.ps-rr-section-title    { font-size: 13px; font-weight: 600; color: #e2e8f0; flex: 1; }
.ps-rr-section-pass     { font-size: 10px; font-weight: 700; }
.ps-rr-empty            { padding: 16px; font-size: 12px; color: #aab4c4; font-style: italic; }

/* Rule row */
.ps-rr-row              { display: flex; align-items: center; gap: 12px; padding: 10px 16px; border-bottom: 1px solid rgba(255,255,255,0.04); transition: background 0.1s; }
.ps-rr-row:hover        { background: rgba(255,255,255,0.03); }
.ps-rr-row--inactive    { opacity: 0.45; }
.ps-rr-row:last-child   { border-bottom: none; }
.ps-rr-row-main         { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0; }
.ps-rr-entity           { font-size: 13px; font-weight: 500; color: #e2e8f0; }
.ps-rr-arrow            { font-size: 12px; color: #94a3b8; }
.ps-rr-template         { font-size: 12px; color: #38bdf8; }
.ps-rr-note             { font-size: 11px; color: #aab4c4; font-style: italic; }
.ps-rr-note--spaced     { margin-bottom: 8px; }
/* Real, new — per direct guidance ("Routing Rules should also be tied
   to a Performing Lab facility"): the Performing Lab hint text in the
   rule modal, and the small lab badge shown on each rule row. */
.ps-rr-lab-hint         { font-size: 11px; color: #94a3b8; margin-top: 4px; }
.ps-rr-lab-badge        { font-size: 10px; font-weight: 600; padding: 1px 6px; border-radius: 4px; background: rgba(130,145,168,0.13); color: #8291a8; border: 1px solid rgba(130,145,168,0.27); }
.ps-rr-row-actions      { display: flex; align-items: center; gap: 6px; opacity: 0; transition: opacity 0.15s; }
.ps-rr-row:hover .ps-rr-row-actions { opacity: 1; }
.ps-rr-toggle           { font-size: 10px; padding: 2px 8px; border-radius: 4px; border: 1px solid rgba(255,255,255,0.1); background: transparent; color: #94a3b8; cursor: pointer; font-family: inherit; }
.ps-rr-toggle--on       { border-color: rgba(16,185,129,0.3); color: #10b981; background: rgba(16,185,129,0.08); }
.ps-rr-btn              { font-size: 11px; padding: 3px 10px; border-radius: 4px; border: 1px solid rgba(255,255,255,0.1); background: transparent; color: #94a3b8; cursor: pointer; font-family: inherit; transition: color 0.15s; }
.ps-rr-btn:hover        { color: #e2e8f0; }
.ps-rr-btn--danger      { color: #f87171; border-color: rgba(248,113,113,0.3); }
.ps-rr-btn--ghost       { color: #94a3b8; }
.ps-rr-confirm-text     { font-size: 11px; color: #f87171; }

/* Modal preview */
.ps-rr-preview          { background: rgba(8,145,178,0.06); border: 1px solid rgba(8,145,178,0.2); border-radius: 6px; padding: 8px 12px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.ps-rr-preview-arrow    { color: #94a3b8; font-size: 14px; }
.ps-rr-preview-entity   { font-size: 12px; font-weight: 600; color: #e2e8f0; }
.ps-rr-preview-always   { font-size: 11px; color: #94a3b8; }
.ps-rr-preview-template { font-size: 12px; font-weight: 600; color: #38bdf8; }

/* Test panel */
.ps-rr-test             { background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.06); border-radius: 8px; padding: 18px; display: flex; flex-direction: column; gap: 12px; align-self: start; position: sticky; top: 0; }
.ps-rr-test-title       { font-size: 13px; font-weight: 700; color: #e2e8f0; }
.ps-rr-test-subtitle    { font-size: 11px; color: #b9c4d4; line-height: 1.5; }
.ps-rr-test-fields      { display: flex; flex-direction: column; gap: 10px; }
.ps-rr-result           { background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; padding: 12px; display: flex; flex-direction: column; gap: 4px; }
.ps-rr-result-template  { font-size: 14px; font-weight: 700; color: #e2e8f0; }
.ps-rr-result-pass      { font-size: 11px; font-weight: 600; }
.ps-rr-result-warn      { font-size: 11px; color: #f59e0b; margin-top: 4px; line-height: 1.5; }

/* ── OrchestratorReportPanel — template indicator bar ────────────────────── */
.ps-orch3-tmpl-bar           { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 8px 12px; background: rgba(8,145,178,0.05); border: 1px solid rgba(8,145,178,0.15); border-radius: 6px; margin-bottom: 16px; flex-wrap: wrap; }
.ps-orch3-tmpl-bar-left      { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.ps-orch3-tmpl-bar-right     { display: flex; align-items: center; gap: 6px; }
.ps-orch3-tmpl-label         { font-size: 10px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.06em; }
.ps-orch3-tmpl-name          { font-size: 12px; font-weight: 600; color: #e2e8f0; }
.ps-orch3-tmpl-by            { font-size: 10px; color: #9ca3af; font-style: italic; }
.ps-orch3-tmpl-by--override  { color: #f59e0b; font-style: normal; font-weight: 600; }
.ps-orch3-tmpl-reset         { font-size: 11px; color: #94a3b8; background: none; border: 1px solid #e5e7eb; border-radius: 4px; padding: 3px 8px; cursor: pointer; font-family: inherit; }
.ps-orch3-tmpl-reset:hover   { color: #374151; }
.ps-orch3-tmpl-change        { font-size: 11px; font-weight: 600; color: #0891B2; background: none; border: 1px solid rgba(8,145,178,0.3); border-radius: 4px; padding: 3px 10px; cursor: pointer; font-family: inherit; }
.ps-orch3-tmpl-change:hover  { background: rgba(8,145,178,0.06); }
.ps-orch3-tmpl-change-wrap   { position: relative; }
.ps-orch3-tmpl-picker        { position: absolute; top: calc(100% + 4px); right: 0; background: white; border: 1px solid #e5e7eb; border-radius: 8px; box-shadow: 0 8px 24px rgba(0,0,0,0.12); min-width: 280px; z-index: 100; overflow: hidden; }
.ps-orch3-tmpl-picker-title  { padding: 10px 14px 6px; font-size: 10px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.06em; border-bottom: 1px solid #f3f4f6; }
.ps-orch3-tmpl-picker-warn   { padding: 8px 14px; font-size: 11px; color: #92400e; background: #fffbeb; border-bottom: 1px solid #fde68a; line-height: 1.5; }
.ps-orch3-tmpl-option        { display: flex; flex-direction: column; gap: 2px; padding: 8px 14px; cursor: pointer; transition: background 0.1s; border-bottom: 1px solid #f9fafb; }
.ps-orch3-tmpl-option:hover  { background: #f9fafb; }
.ps-orch3-tmpl-option--active{ background: #eff6ff; }
.ps-orch3-tmpl-option:last-child { border-bottom: none; }
.ps-orch3-tmpl-option-name   { font-size: 12px; font-weight: 500; color: #94a3b8; }
.ps-orch3-tmpl-option-meta   { font-size: 10px; color: #9ca3af; }

/* ── Validation Studies ──────────────────────────────────────────────────── */
.ps-vs-root                  { display: flex; flex-direction: column; height: 100%; gap: 0; }
.ps-vs-header                { margin-bottom: 16px; }
.ps-vs-header-title          { font-size: 20px; font-weight: 700; color: #e2e8f0; margin-bottom: 4px; }
.ps-vs-header-sub            { font-size: 12px; color: #64748b; margin-bottom: 10px; line-height: 1.5; }
.ps-vs-advisory-banner       { display: inline-flex; align-items: center; gap: 8px; font-size: 11px; font-weight: 600; color: #1e40af; background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 6px; padding: 6px 12px; }
.ps-vs-content               { flex: 1; min-height: 0; overflow-y: auto; padding-top: 16px; }
.ps-sub-tab-group            { display: flex; gap: 3px; padding: 3px; background: rgba(255,255,255,0.03); border: 1px solid #1e293b; border-radius: 8px; align-self: flex-start; margin-bottom: 0; }

/* Real, per direct report: "the top of the button is up against the
   bottom border of the tab row." Confirmed the real, precise cause —
   the shared base rule above has margin-bottom: 0, and neither
   ps-conf-section-header (margin-top: none) nor ps-confsys-content
   (padding-top: none) provide any real gap either. Real, scoped
   modifier — the shared class's own zero margin is correct and used
   elsewhere (Validation Studies' own Studies/Dashboard/Reports row),
   so this is additive here, not a change to the shared rule. */
.ps-sub-tab-group--gap-below { margin-bottom: 20px; }

/* Studies tab */
.ps-vs-studies               { display: flex; flex-direction: column; gap: 12px; }
.ps-vs-section-header        { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 8px; }
.ps-vs-section-title         { font-size: 14px; font-weight: 600; color: #e2e8f0; margin-bottom: 4px; }
.ps-vs-section-sub           { font-size: 11px; color: #94a3b8; line-height: 1.6; max-width: 600px; }
.ps-vs-study-row             { background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.06); border-radius: 8px; padding: 14px 16px; display: flex; align-items: flex-start; gap: 16px; }
.ps-vs-study-row-main        { flex: 1; min-width: 0; }
.ps-vs-study-name            { font-size: 14px; font-weight: 600; color: #e2e8f0; margin-bottom: 6px; }
.ps-vs-study-meta            { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; font-size: 11px; color: #64748b; margin-bottom: 4px; }
.ps-vs-study-badge           { font-size: 10px; font-weight: 700; padding: 2px 8px; border-radius: 4px; border: 1px solid var(--ps-vs-badge-border, currentColor); color: var(--ps-vs-badge-color, inherit); background: var(--ps-vs-badge-bg, transparent); }
.ps-vs-study-desc            { font-size: 12px; color: #94a3b8; margin-top: 4px; }
.ps-vs-study-actions         { display: flex; gap: 6px; flex-shrink: 0; }
.ps-vs-empty                 { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 48px 24px; text-align: center; }
.ps-vs-empty-icon            { font-size: 40px; margin-bottom: 14px; opacity: 0.25; }
.ps-vs-empty-title           { font-size: 14px; font-weight: 600; color: #94a3b8; margin-bottom: 8px; }
.ps-vs-empty-body            { font-size: 12px; color: #94a3b8; max-width: 340px; line-height: 1.6; }

/* Form */
.ps-vs-form-2col             { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.ps-vs-slider-wrap           { display: flex; align-items: center; gap: 10px; margin-top: 4px; }
.ps-vs-slider                { flex: 1; accent-color: #0891B2; }
.ps-vs-slider-val            { font-size: 14px; font-weight: 700; color: #0891B2; min-width: 42px; }
.ps-vs-slider-hint           { font-size: 10px; color: #94a3b8; margin-top: 4px; }
.ps-vs-checklist             { display: flex; flex-direction: column; gap: 6px; max-height: 180px; overflow-y: auto; background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.07); border-radius: 6px; padding: 10px 12px; }
.ps-vs-check-row             { display: flex; align-items: center; gap: 8px; font-size: 12px; color: #94a3b8; cursor: pointer; }
.ps-vs-check-row input       { accent-color: #0891B2; }

/* Dashboard */
.ps-vs-dashboard             { display: flex; flex-direction: column; gap: 20px; }
.ps-vs-study-select-wrap     { display: flex; align-items: center; gap: 12px; }
.ps-vs-kpi-row               { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.ps-vs-kpi                   { background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.07); border-radius: 8px; padding: 14px; }
.ps-vs-kpi-val               { font-size: 28px; font-weight: 700; color: #e2e8f0; line-height: 1; margin-bottom: 4px; }
.ps-vs-kpi-label             { font-size: 11px; color: #64748b; text-transform: uppercase; letter-spacing: 0.05em; }
.ps-vs-kpi-target            { font-size: 10px; color: #94a3b8; margin-top: 4px; }
.ps-vs-table-wrap            { background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.07); border-radius: 8px; overflow: hidden; }
.ps-vs-table-title           { font-size: 11px; font-weight: 700; color: #64748b; text-transform: uppercase; letter-spacing: 0.06em; padding: 10px 14px; border-bottom: 1px solid rgba(255,255,255,0.06); }
.ps-vs-table                 { width: 100%; border-collapse: collapse; }
.ps-vs-table th              { text-align: left; padding: 8px 14px; font-size: 10px; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.05em; background: rgba(255,255,255,0.02); }
.ps-vs-table td              { padding: 8px 14px; font-size: 12px; color: #94a3b8; border-top: 1px solid rgba(255,255,255,0.04); }
.ps-vs-td-name               { color: #e2e8f0; text-transform: capitalize; }
.ps-vs-td-edittype           { font-style: italic; color: #64748b; }
.ps-vs-advisory-notice       { font-size: 11px; color: #94a3b8; background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.06); border-radius: 6px; padding: 8px 12px; }

/* Reports */
.ps-vs-reports               { display: flex; flex-direction: column; gap: 16px; }
.ps-vs-report-preview        { background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.07); border-radius: 8px; padding: 20px; }
.ps-vs-report-preview-title  { font-size: 14px; font-weight: 600; color: #e2e8f0; margin-bottom: 14px; }
.ps-vs-report-kpis           { display: flex; flex-direction: column; gap: 8px; }
.ps-vs-report-kpis > div     { display: flex; gap: 16px; font-size: 12px; }
.ps-vs-rp-label              { color: #64748b; min-width: 140px; font-weight: 500; }

/* batch 28 additions — ps-vs- class extensions for i18n/cleanup sweep.
   Good/bad metric coloring replaces the old inline
   `style={{ color: pass ? green : red }}` pattern with two modifier
   classes, so the comparison result drives a class instead of a literal
   color computed inline on every render. */
.ps-vs-metric--good           { color: #10b981; }
.ps-vs-metric--bad            { color: #f87171; }
.ps-vs-kpi--good              { border-color: #10b981; }
.ps-vs-kpi--bad               { border-color: #f87171; }
.ps-vs-kpi--good .ps-vs-kpi-val--metric { color: #10b981; }
.ps-vs-kpi--bad .ps-vs-kpi-val--metric  { color: #f87171; }
.ps-vs-select--wide           { max-width: 380px; }
.ps-vs-hint--spaced           { margin-top: 4px; margin-bottom: 6px; }
.ps-vs-empty--spaced          { margin-top: 24px; }
.ps-vs-reports-select-wrap    { margin-bottom: 16px; }
.ps-vs-generate-btn           { margin-top: 16px; }
.ps-vs-store-link             { margin-top: 6px; background: none; border: none; padding: 0; color: #38bdf8; font-size: 11px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 4px; }
.ps-vs-howitworks-toggle      { margin-top: 10px; font-size: 12px; }
.ps-vs-howitworks-panel       { margin-top: 10px; padding: 14px 16px; border-radius: 8px; background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); font-size: 13px; line-height: 1.7; color: #cbd5e1; }
.ps-vs-howitworks-p           { margin: 0 0 10px; }
.ps-vs-howitworks-beta        { color: #fbbf24; }
.ps-vs-howitworks-example-heading { margin: 0 0 6px; font-weight: 700; color: #e2e8f0; }
.ps-vs-howitworks-list        { margin: 0 0 10px; padding-left: 20px; }
.ps-vs-howitworks-footer      { margin: 0; color: #94a3b8; }

/* StudyFormModal — a taller/wider variant of the shared .ps-modal-dark. */
.ps-vs-studyform-modal        { width: 640px; max-height: 85vh; overflow: auto; }
.ps-vs-studyform-body         { padding: 20px 24px; display: flex; flex-direction: column; gap: 16px; }

/* ── Validation Studies — governance modals ──────────────────────────────── */
