.ps-rd-tri-dash                  { color: #8AB4F8; font-weight: 900; line-height: 1; font-size: calc(var(--rd-cb-size, 16px) * 0.75); }

/* Client access tab */

/* Custom checkboxes (div-based) */
.ps-rd-cb                        { width: var(--rd-cb-size, 16px); height: var(--rd-cb-size, 16px); border-radius: 4px; flex-shrink: 0; display: flex; align-items: center; justify-content: center; transition: all 0.15s; cursor: pointer; }
.ps-rd-cb--size-16               { --rd-cb-size: 16px; }
.ps-rd-cb--size-18               { --rd-cb-size: 18px; }
.ps-rd-cb--size-20               { --rd-cb-size: 20px; }
.ps-rd-cb--off                   { border: 2px solid #374151; background: transparent; }
.ps-rd-cb--on-blue               { border: 2px solid #8AB4F8; background: #8AB4F8; }
.ps-rd-cb--on-green              { border: 2px solid #22c55e; background: #22c55e; }

/* Participation tab */
.ps-rd-part-tab                  { flex: 1; overflow-y: auto; padding: 20px 24px; }
.ps-rd-part-intro                { font-size: 13px; color: #94a3b8; margin-bottom: 8px; line-height: 1.6; }
.ps-rd-part-warn                 { margin-bottom: 16px; padding: 8px 12px; border-radius: 8px; background: rgba(251,191,36,0.08); border: 1px solid rgba(251,191,36,0.2); color: #fbbf24; font-size: 12px; }
.ps-rd-part-empty                { padding: 40px 20px; text-align: center; color: #94a3b8; font-size: 13px; border: 1px dashed rgba(255,255,255,0.08); border-radius: 12px; }
.ps-rd-part-list                 { display: flex; flex-direction: column; gap: 6px; margin-top: 16px; }
