.ps-rd-part-item--off:hover      { background: rgba(255,255,255,0.04); }
.ps-rd-part-name                 { font-size: 13px; font-weight: 600; margin-bottom: 4px; }
.ps-rd-part-name--on             { color: #e5e7eb; }
