.wl-pool-substate--grossed {
  background: rgba(16,185,129,0.15);
  color: #10b981;
  border: 1px solid rgba(16,185,129,0.3);
}

.wl-pool-substate--mixed {
  background: rgba(167,139,250,0.15);
  color: #a78bfa;
  border: 1px solid rgba(167,139,250,0.3);
}

/* Card view's own report-breakdown badge sits inline after the status
   pill rather than inside .wl-status-wrap, so it needs its own small
   left gap (batch 31, replacing style={{ marginLeft: 6 }}). */
.wl-pool-substate--spaced { margin-left: 6px; }

