.ps-plib__new-btn  { background: #0891b2; border: none; color: #fff; font-size: 12.5px; font-weight: 600;
  padding: 8px 16px; border-radius: 7px; cursor: pointer; flex-shrink: 0; font-family: inherit; }
.ps-plib__new-btn:hover { background: #07748f; }

/* ── Error banner ─────────────────────────────────────────────── */
.ps-plib__error { display: flex; align-items: center; justify-content: space-between;
  background: rgba(239,68,68,0.1); border: 1px solid rgba(239,68,68,0.3); border-radius: 7px;
  padding: 10px 14px; margin-bottom: 14px; color: #fca5a5; font-size: 12.5px; }
.ps-plib__error-dismiss { background: none; border: none; color: #fca5a5; cursor: pointer; font-size: 13px; }

/* ── Filter bar ───────────────────────────────────────────────── */
.ps-plib__filters     { display: flex; align-items: center; justify-content: space-between;
  gap: 16px; margin-bottom: 16px; flex-wrap: wrap; }
.ps-plib__filter-group { display: flex; gap: 6px; flex-wrap: wrap; }
.ps-plib__filter-btn   { background: #1e293b; border: 1px solid #334155; color: #b9c4d4;
