  font-family: inherit; }
.ps-plib__search::placeholder { color: #94a3b8; }
.ps-plib__search:focus { border-color: #0891b2; }

/* ── Loading / empty states ───────────────────────────────────── */
.ps-plib__loading { padding: 32px; text-align: center; color: #b9c4d4; font-size: 13px; }
.ps-plib__empty    { padding: 16px 8px 20px; color: #94a3b8; font-size: 12.5px; font-style: italic; }

/* ── Type group header ────────────────────────────────────────── */
.ps-plib__group-header { display: flex; align-items: center; gap: 8px; padding: 14px 4px 8px;
  border-top: 1px solid rgba(255,255,255,0.06); margin-top: 6px; }
.ps-plib__group-header:first-of-type { border-top: none; margin-top: 0; }
.ps-plib__group-icon  { font-size: 13px; }
.ps-plib__group-icon--header  { color: #60a5fa; }
.ps-plib__group-icon--body    { color: #4ade80; }
.ps-plib__group-icon--footer  { color: #c084fc; }
.ps-plib__group-label { font-size: 12px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; }
.ps-plib__group-label--header { color: #93c5fd; }
.ps-plib__group-label--body   { color: #86efac; }
.ps-plib__group-label--footer { color: #d8b4fe; }
.ps-plib__group-count { font-size: 11px; font-weight: 700; color: #94a3b8; background: rgba(255,255,255,0.06);
  border-radius: 10px; padding: 1px 8px; margin-left: 2px; }

/* ── Part card (Config tab list row) ─────────────────────────── */
.ps-plib-card { display: flex; align-items: flex-start; gap: 12px; padding: 12px 8px;
  border-bottom: 1px solid rgba(255,255,255,0.05); transition: background 0.12s; }
.ps-plib-card:hover { background: rgba(255,255,255,0.025); }
.ps-plib-card.confirm-active { background: rgba(239,68,68,0.06); }

.ps-plib-card__icon { width: 32px; height: 32px; border-radius: 7px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700;
  margin-top: 2px; }
.ps-plib-card__icon--header { background: rgba(59,130,246,0.12); color: #60a5fa; }
.ps-plib-card__icon--body   { background: rgba(34,197,94,0.12);  color: #4ade80; }
.ps-plib-card__icon--footer { background: rgba(168,85,247,0.12); color: #c084fc; }

.ps-plib-card__info     { flex: 1; min-width: 0; }
.ps-plib-card__name-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.ps-plib-card__name     { font-size: 13.5px; font-weight: 600; color: #f1f5f9; }
.ps-plib-card__desc     { font-size: 12px; color: #aab4c4; margin-top: 3px; line-height: 1.4; }

.ps-plib-card__badge { font-size: 9.5px; font-weight: 700; letter-spacing: 0.03em; text-transform: uppercase;
  padding: 2px 7px; border-radius: 10px; }
.ps-plib-card__badge--published { background: rgba(14,159,110,0.16); color: #34d399; }
.ps-plib-card__badge--draft     { background: rgba(234,179,8,0.16);  color: #facc15; }
.ps-plib-card__badge--archived  { background: rgba(100,116,139,0.2); color: #b9c4d4; }
.ps-plib-card__badge--builtin   { background: rgba(8,145,178,0.18);  color: #38bdf8; }
/* Real, new — per direct guidance ("Parts Library... should also be
   tied to a Performing Lab facility"). Neutral, not a status color —
   this is informational (which lab, or Global), not a state signal. */
.ps-plib-card__badge--lab       { background: rgba(130,145,168,0.13); color: #8291a8; border: 1px solid rgba(130,145,168,0.27); }

.ps-plib-card__actions { display: flex; align-items: center; gap: 6px; flex-shrink: 0; margin-top: 2px; }
.ps-plib-card__btn { font-size: 11.5px; font-weight: 600; padding: 5px 12px; border-radius: 6px;
  cursor: pointer; border: 1px solid transparent; font-family: inherit; white-space: nowrap; }
.ps-plib-card__btn--primary   { background: rgba(8,145,178,0.16); border-color: rgba(8,145,178,0.4); color: #38bdf8; }
.ps-plib-card__btn--primary:hover { background: rgba(8,145,178,0.28); }
.ps-plib-card__btn--secondary { background: #1e293b; border-color: #94a3b8; color: #b9c4d4; }
.ps-plib-card__btn--secondary:hover { color: #e2e8f0; border-color: #94a3b8; }
.ps-plib-card__btn--secondary:disabled { opacity: 0.5; cursor: default; }
.ps-plib-card__btn--cancel    { background: none; border-color: #94a3b8; color: #94a3b8; }
.ps-plib-card__btn--cancel:hover { color: #e2e8f0; border-color: #94a3b8; }
.ps-plib-card__btn--danger    { background: rgba(239,68,68,0.14); border-color: rgba(239,68,68,0.4); color: #f87171; }
.ps-plib-card__btn--danger:hover { background: rgba(239,68,68,0.24); }
.ps-plib-card__confirm-text { font-size: 11.5px; color: #fca5a5; margin-right: 2px; }

.ps-conf-loading { padding: 32px; text-align: center; font-size: 13px; color: #b9c4d4; }

/* ============================================================
   REPORT TEMPLATES SECTION WRAPPER — ps-rts-*
   src/components/TemplateBuilder/ReportTemplatesSection.tsx
   ============================================================ */
.ps-rts-root     { display: flex; flex-direction: column; height: 100%; }
.ps-rts-subtabs  { display: flex; gap: 3px; margin-bottom: 20px; padding: 3px;
  background: rgba(255,255,255,0.03); border: 1px solid #1e293b; border-radius: 8px;
  align-self: flex-start; }
.ps-rts-content  { flex: 1; min-height: 0; }

/* ============================================================
   ROUTING RULES TAB — additional ps-rr-* classes
   src/components/TemplateBuilder/RoutingRulesTab.tsx
   ============================================================ */
.ps-rr-modal-body { display: flex; flex-direction: column; gap: 14px; padding: 20px 24px; }
.ps-rr-test-btn   { margin-top: 8px; }

.ps-rr-pass--client-override      { color: #f59e0b; }
.ps-rr-pass--physician-preference { color: #a78bfa; }
.ps-rr-pass--cap-protocol         { color: #10b981; }
.ps-rr-pass--subspecialty         { color: #38bdf8; }
