.ps-cassrr-conditions-summary { font-size: 13px; color: #cbd5e1; }

/* ============================================================
   TEMPLATE PALETTE — ps-tpal-*
   src/components/TemplateBuilder/TemplatePalette.tsx
   Colours preserved exactly from the original WCAG-verified
   inline values (see comments in the .tsx for contrast ratios).
   Per-item icon colour is genuinely dynamic (sourced from
   PALETTE_ITEMS data, one of ~18 distinct values) so it's passed
   through via --tpal-color and blended with color-mix() here,
   rather than hardcoding 18 modifier classes.
   ============================================================ */

.ps-tpal-root   { width: 220px; min-width: 220px; background: #0d1117;
  border-right: 1px solid rgba(255,255,255,0.08); display: flex; flex-direction: column;
  overflow: hidden; flex-shrink: 0; font-family: 'Inter','Segoe UI',system-ui,sans-serif; }
.ps-tpal-header { padding: 12px 12px 10px; border-bottom: 1px solid rgba(255,255,255,0.08); flex-shrink: 0; }
.ps-tpal-header-title { font-size: 11px; font-weight: 700; color: #f1f5f9; letter-spacing: 0.06em; text-transform: uppercase; }
.ps-tpal-header-sub   { font-size: 10px; color: #94a3b8; margin-top: 2px; }
.ps-tpal-groups { flex: 1; overflow-y: auto; }

.ps-tpal-group        { border-bottom: 1px solid rgba(255,255,255,0.07); }
.ps-tpal-group-header  { width: 100%; display: flex; align-items: center; gap: 8px; padding: 8px 12px;
  background: transparent; border: none; cursor: pointer; transition: background 0.1s; font-family: inherit; }
.ps-tpal-group-header--open { background: rgba(255,255,255,0.03); border-bottom: 1px solid rgba(255,255,255,0.06); }
.ps-tpal-group-icon    { font-size: 12px; color: #64748b; flex-shrink: 0; }
.ps-tpal-group-label   { font-size: 10px; font-weight: 700; color: #cbd5e1; letter-spacing: 0.07em;
  text-transform: uppercase; flex: 1; text-align: left; }
.ps-tpal-group-count   { font-size: 10px; color: #94a3b8; background: rgba(255,255,255,0.06);
  padding: 1px 6px; border-radius: 10px; flex-shrink: 0; }
.ps-tpal-group-chevron { font-size: 10px; color: #94a3b8; flex-shrink: 0; display: inline-block;
  transform: rotate(0deg); transition: transform 0.15s; }
.ps-tpal-group-chevron--closed { transform: rotate(-90deg); }

.ps-tpal-item { display: flex; align-items: center; gap: 10px; padding: 7px 12px; cursor: grab;
  user-select: none; background: transparent; border-bottom: 1px solid rgba(255,255,255,0.05);
  transition: background 0.1s; }
.ps-tpal-item--hovered { background: rgba(255,255,255,0.06); }

.ps-tpal-item-icon { width: 30px; height: 30px; border-radius: 7px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700;
  background: color-mix(in srgb, var(--tpal-color) 13%, transparent);
  border: 1.5px solid color-mix(in srgb, var(--tpal-color) 33%, transparent);
  color: var(--tpal-color); }

.ps-tpal-item-labels   { min-width: 0; }
.ps-tpal-item-label    { font-size: 12px; font-weight: 600; color: #e2e8f0; white-space: nowrap;
  overflow: hidden; text-overflow: ellipsis; line-height: 1.3; }
.ps-tpal-item-subtitle { font-size: 10px; color: #94a3b8; white-space: nowrap; overflow: hidden;
  text-overflow: ellipsis; line-height: 1.3; margin-top: 1px; }
.ps-tpal-item-drag-hint { margin-left: auto; font-size: 12px; color: #64748b; flex-shrink: 0; }

/* ============================================================
   TEMPLATE CANVAS — ps-tc-*
   src/components/TemplateBuilder/TemplateCanvas.tsx
   Per-node palette colour (--node-color) is genuinely dynamic —
   sourced from PALETTE_ITEMS, ~18 distinct values — so it's
   passed through via CSS custom property and blended with
   color-mix() here rather than hardcoding per-type classes.
   Per-node/per-row colSpan (1–12, arbitrary) remains inline as
   `gridColumn: span N` since it's a genuine computed layout value.
   ============================================================ */

.ps-tc-canvas-surround { flex: 1; overflow-y: auto; background: #1e2535; padding: 32px 40px;
  min-height: 0; display: flex; flex-direction: column; align-items: center; }
.ps-tc-page { width: 100%; max-width: 820px; min-height: 1000px; background: #ffffff;
  border-radius: 3px; box-shadow: 0 4px 6px rgba(0,0,0,0.3), 0 20px 60px rgba(0,0,0,0.4);
  display: flex; flex-direction: column;
  /* No overflow:hidden — it clips backgroundImage on child divs */ }

/* ── Header/footer zones ─────────────────────────────────────── */
.ps-tc-zone { position: relative; }
.ps-tc-zone--header { min-height: 72px; padding: 10px 24px; border-bottom: 1.5px dashed #cbd5e1;
  background: #f8fafc; position: relative; transition: background 0.15s, border-color 0.15s; }
.ps-tc-zone--footer { min-height: 56px; padding: 10px 24px; border-top: 1.5px dashed #cbd5e1;
  background: #f8fafc; position: relative; transition: background 0.15s, border-color 0.15s; }
.ps-tc-zone--header--p2plus { min-height: 72px; padding: 10px 24px; position: relative;
  background: #eef2ff; border-top: 1px solid #c7d2fe; border-bottom: 1px solid #c7d2fe;
  transition: background 0.15s, border-color 0.15s; }
.ps-tc-zone--footer--p2plus { min-height: 56px; padding: 10px 24px; position: relative;
  background: #eef2ff; border-top: 1px solid #c7d2fe; border-bottom: 1px solid #c7d2fe;
  transition: background 0.15s, border-color 0.15s; }
.ps-tc-zone--drag-over { background: rgba(8,145,178,0.06) !important; border-color: #0891b2 !important; }

.ps-tc-zone-label-row { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.ps-tc-zone-label { font-size: 9px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase;
  color: #94a3b8; /* WCAG: #475569 on #f8fafc = 5.9:1 ✓ */ }
.ps-tc-zone-hint  { font-size: 11px; color: #64748b; font-style: italic; /* 4.6:1 ✓ */ }
.ps-tc-zone-chips { display: flex; gap: 3px; }
.ps-tc-zone-chip  { font-size: 9px; font-weight: 600; padding: 1px 6px; border-radius: 3px;
  background: rgba(8,145,178,0.12); color: #0891b2; letter-spacing: 0.03em; white-space: nowrap; }

/* ── Body area ────────────────────────────────────────────────── */
.ps-tc-body { flex: 1; padding: 20px 24px; min-height: 600px; background-image: none; }
.ps-tc-body--grid { background-image: radial-gradient(circle, rgba(0,0,0,0.22) 1.5px, transparent 1.5px);
  background-size: 24px 24px; }

.ps-tc-body-empty { display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 60px 20px; gap: 8px; border: 2px dashed #cbd5e1; border-radius: 8px; margin: 8px;
  background: transparent; transition: all 0.15s; }
.ps-tc-body-empty--dragging { border-color: #0891b2; background: rgba(8,145,178,0.04); }
.ps-tc-body-empty-icon  { font-size: 32px; color: #94a3b8; opacity: 0.5; }
.ps-tc-body-empty--dragging .ps-tc-body-empty-icon { color: #0891b2; }
.ps-tc-body-empty-title { font-size: 13px; font-weight: 600; color: #94a3b8; }
.ps-tc-body-empty--dragging .ps-tc-body-empty-title { color: #0891b2; }
.ps-tc-body-empty-sub   { font-size: 11px; color: #64748b; text-align: center; max-width: 260px; }

.ps-tc-row-grid { display: grid; grid-template-columns: repeat(12, 1fr); gap: 0 6px; margin-bottom: 3px; }
.ps-tc-free-slot { min-height: 40px; border: 1.5px dashed #e2e8f0; border-radius: 6px;
  display: flex; align-items: center; justify-content: center; font-size: 10px; color: #94a3b8;
  background: transparent; cursor: default; transition: all 0.15s; }
.ps-tc-free-slot--dragging { border-color: #0891b2; color: #0891b2; background: rgba(8,145,178,0.05); cursor: copy; }

/* ── Drop zone ────────────────────────────────────────────────── */
.ps-tc-dropzone { height: 6px; margin: 1px 0; border-radius: 4px; background: transparent;
  border: 1.5px solid transparent; transition: all 0.12s; display: none; }
.ps-tc-dropzone--active { display: block; }
.ps-tc-dropzone--over   { height: 32px; background: rgba(14,159,110,0.18); border: 1.5px dashed #0e9f6e; }

/* ── Node wrap / width label ──────────────────────────────────── */
.ps-tc-node-wrap { position: relative; }
.ps-tc-node-wrap--grid { outline: 1px dashed rgba(8,145,178,0.2); outline-offset: 1px; }
.ps-tc-width-label { position: absolute; top: -14px; right: 4px; font-size: 8px;
  color: rgba(8,145,178,0.6); font-weight: 700; letter-spacing: 0.04em; pointer-events: none;
  background: #fff; padding: 0 3px; border-radius: 2px; }

/* ── Node row (per-node-type palette colour via --node-color) ──── */
.ps-tc-node-row { display: flex; align-items: center; gap: 8px; padding: 6px 10px 6px 0;
  border-radius: 6px; cursor: grab; transition: all 0.1s; margin-bottom: 3px;
  opacity: 1; position: relative; overflow: hidden;
  border: 1.5px solid color-mix(in srgb, var(--node-color) 19%, transparent);
  background: color-mix(in srgb, var(--node-color) 3%, transparent);
  box-shadow: 0 1px 2px rgba(0,0,0,0.06); }
.ps-tc-node-row--hovered {
  background: color-mix(in srgb, var(--node-color) 5%, transparent); }
.ps-tc-node-row--selected {
  border-color: color-mix(in srgb, var(--node-color) 73%, transparent);
  background: color-mix(in srgb, var(--node-color) 9%, transparent);
  box-shadow: 0 1px 4px color-mix(in srgb, var(--node-color) 13%, transparent); }
.ps-tc-node-row--dragging { opacity: 0.4; }

.ps-tc-node-accent { position: absolute; left: 0; top: 0; bottom: 0; width: 3px;
  border-radius: 6px 0 0 6px; transition: background 0.1s;
  background: color-mix(in srgb, var(--node-color) 38%, transparent); }
.ps-tc-node-accent--selected { background: var(--node-color); }

.ps-tc-node-spacer      { width: 6px; flex-shrink: 0; }
.ps-tc-node-spacer-wide { width: 14px; flex-shrink: 0; }
.ps-tc-node-expand-btn  { background: none; border: none; color: var(--node-color); cursor: pointer;
  padding: 0 2px; font-size: 10px; line-height: 1; flex-shrink: 0; opacity: 0.7; font-family: inherit; }

.ps-tc-node-icon { width: 24px; height: 24px; border-radius: 5px; display: flex; align-items: center;
  justify-content: center; font-size: 11px; font-weight: 700; flex-shrink: 0;
  background: color-mix(in srgb, var(--node-color) 13%, transparent); color: var(--node-color); }

.ps-tc-node-label-col { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.ps-tc-node-label { font-size: 12px; font-weight: 600; color: #94a3b8; overflow: hidden;
  text-overflow: ellipsis; white-space: nowrap; }
.ps-tc-node-label--selected { color: var(--node-color); }

.ps-tc-node-chips { display: flex; gap: 3px; flex-wrap: wrap; }
.ps-tc-node-chip   { font-size: 9px; font-weight: 700; padding: 1px 5px; border-radius: 3px;
  /* WCAG: #374151 on light tinted bg ≈ 9:1 ✓ */
  background: color-mix(in srgb, var(--node-color) 13%, transparent); color: #374151;
  border: 1px solid color-mix(in srgb, var(--node-color) 25%, transparent);
  letter-spacing: 0.03em; white-space: nowrap; }

.ps-tc-badge { font-size: 9px; font-weight: 700; padding: 1px 5px; border-radius: 3px; flex-shrink: 0;
  letter-spacing: 0.04em; }
.ps-tc-badge--ai { background: #d1fae5; color: #065f46; border: 1px solid #6ee7b7; } /* 7.5:1 ✓ */
.ps-tc-badge--if { background: #fef3c7; color: #713f12; border: 1px solid #fcd34d; } /* 8.1:1 ✓ */

.ps-tc-node-delete-btn { background: rgba(239,68,68,0.1); border: 1px solid rgba(239,68,68,0.2);
  color: #dc2626; cursor: pointer; padding: 2px 5px; font-size: 10px; border-radius: 3px;
  line-height: 1; flex-shrink: 0; font-family: inherit; }

/* ── Resize handle ────────────────────────────────────────────── */
.ps-tc-resize-handle { position: absolute; top: 0; right: -3px; width: 8px; height: 100%;
  cursor: col-resize; z-index: 10; display: flex; align-items: center; justify-content: center;
  opacity: 0; transition: opacity 0.15s; }
.ps-tc-resize-handle--visible { opacity: 1; }
.ps-tc-resize-bar { width: 3px; height: 24px; border-radius: 2px; background: #475569; }
.ps-tc-resize-bar--selected { background: var(--node-color); }

/* ── Column-layout indicator (static teal accent, not per-node-color) ── */
.ps-tc-collayout { margin-left: 8px; margin-top: 4px; }
.ps-tc-collayout-indicator { display: flex; align-items: center; gap: 5px; padding: 5px 8px;
  margin-bottom: 5px; background: rgba(14,159,110,0.07); border: 1px solid rgba(14,159,110,0.18);
  border-radius: 4px; }
.ps-tc-collayout-stripe  { flex: 1; height: 4px; border-radius: 2px; background: rgba(14,159,110,0.35); }
.ps-tc-collayout-divider { width: 1px; height: 14px; background: rgba(14,159,110,0.25); }
.ps-tc-collayout-label   { font-size: 9px; font-weight: 700; color: #0e9f6e; margin-left: 6px;
  flex-shrink: 0; letter-spacing: 0.04em; }
.ps-tc-collayout-list  { padding: 4px 6px; background: rgba(14,159,110,0.03);
  border: 1px dashed rgba(14,159,110,0.2); border-radius: 4px; }
.ps-tc-collayout-empty { font-size: 10px; color: #0e9f6e; text-align: center; padding: 10px 0;
  font-style: italic; opacity: 0.65; }

/* ── 12-col grid children (border colour is per-node-type) ──────── */
.ps-tc-grid-children { margin-left: 16px; padding-left: 8px;
  border-left: 2px solid color-mix(in srgb, var(--node-color) 25%, transparent); }
.ps-tc-grid-span-12 { grid-column: span 12; }
.ps-tc-grid-12 { display: grid; grid-template-columns: repeat(12, 1fr); gap: 2px 4px; position: relative; }
.ps-tc-grid-empty { padding: 10px 12px; font-size: 11px; color: #94a3b8; font-style: italic;
  text-align: center; border: 1.5px dashed #e2e8f0; border-radius: 5px; background: #f8fafc; margin: 4px 0; }

/* ============================================================
   TEMPLATE PREVIEW PANEL — ps-tpp-*
   src/components/TemplateBuilder/TemplatePreviewPanel.tsx
   This is a WYSIWYG print-layout engine — page dimensions,
   margins, column counts/gaps, and per-node colSpan are all
   genuinely computed per render (from mm-to-px conversion, user
   page-size/margin settings, or per-node config) and remain
   inline by necessity. Everything else (fixed dark toolbar
   chrome, fixed print-document typography) is a class below.
   ============================================================ */

/* ── Field table (synoptic-style key/value rows) ─────────────── */
.ps-tpp-field-table { margin-bottom: 5px; }
.ps-tpp-field-row    { display: grid; gap: 0 20px; padding: 3px 0; background: transparent; }
.ps-tpp-field-row--alt { background: rgba(0,0,0,0.018); }
.ps-tpp-field-cell   { display: flex; gap: 8px; align-items: baseline; min-width: 0; }
.ps-tpp-field-label  { font-size: 10px; font-weight: 600; color: #64748b; text-transform: uppercase;
  letter-spacing: 0.04em; flex-shrink: 0; max-width: 42%; overflow: hidden; text-overflow: ellipsis;
  white-space: nowrap; }
.ps-tpp-field-value  { font-size: 12px; color: #e2e8f0; line-height: 1.4; flex: 1; min-width: 0; }

/* ── Static label variants (printed headings) ────────────────── */
.ps-tpp-static-label { display: block; }
.ps-tpp-static-label--h1      { font-size: 15px; font-weight: 700; color: #e2e8f0; margin: 10px 0 3px; }
.ps-tpp-static-label--h2      { font-size: 13px; font-weight: 700; color: #94a3b8; margin: 8px 0 3px; }
.ps-tpp-static-label--h3      { font-size: 12px; font-weight: 600; color: #94a3b8; margin: 6px 0 2px; }
.ps-tpp-static-label--body    { font-size: 12px; color: #94a3b8; margin: 2px 0; }
.ps-tpp-static-label--caption { font-size: 10px; color: #64748b; margin: 2px 0; font-style: italic; }
.ps-tpp-static-label--bold    { font-weight: 700; }
.ps-tpp-static-label--italic  { font-style: italic; }

/* ── Paragraph / rich text ────────────────────────────────────── */
.ps-tpp-paragraph       { margin-bottom: 10px; }
.ps-tpp-paragraph-label { font-size: 10px; font-weight: 700; color: #94a3b8; text-transform: uppercase;
  letter-spacing: 0.05em; margin-bottom: 4px; }
.ps-tpp-paragraph-text  { font-size: 12px; color: #e2e8f0; line-height: 1.7; white-space: pre-wrap; }
.ps-tpp-richtext        { color: #e2e8f0; line-height: 1.7; margin-bottom: 8px; }
.ps-tpp-no-content      { color: #94a3b8; font-style: italic; }
.ps-tpp-no-items        { font-size: 11px; color: #94a3b8; font-style: italic; margin-bottom: 8px; }
.ps-tpp-repeat-item     { margin-bottom: 12px; }

/* ── Section ──────────────────────────────────────────────────── */
.ps-tpp-section         { margin-bottom: 14px; }
.ps-tpp-section-heading { font-size: 10px; font-weight: 800; color: #94a3b8; text-transform: uppercase;
  letter-spacing: 0.08em; border-bottom: 1.5px solid #e2e8f0; padding-bottom: 4px; margin-bottom: 8px; }

/* ── Column layout (newsprint flow) ──────────────────────────── */
.ps-tpp-col-layout       { column-rule: 1px solid #e2e8f0; margin-bottom: 10px; }
.ps-tpp-col-layout-child { break-inside: avoid; margin-bottom: 6px; }

/* ── Image embed ──────────────────────────────────────────────── */
.ps-tpp-image-wrap        { margin: 6px 0; }
.ps-tpp-image             { object-fit: contain; }
.ps-tpp-image-placeholder { background: #f1f5f9; border: 1px dashed #cbd5e1; border-radius: 4px;
  display: inline-flex; align-items: center; justify-content: center; font-size: 10px; color: #94a3b8; }
.ps-tpp-image-caption     { font-size: 9px; color: #64748b; margin-top: 2px; }

/* ── Printed header/footer/template-ref ──────────────────────── */
.ps-tpp-print-header        { display: flex; justify-content: space-between; align-items: flex-start;
  padding-bottom: 8px; margin-bottom: 10px; border-bottom: 2.5px solid #0891b2; }
.ps-tpp-print-header-logo   { font-size: 15px; font-weight: 800; color: #0891b2; }
.ps-tpp-print-header-sub    { font-size: 10px; color: #94a3b8; margin-top: 1px; }
.ps-tpp-print-header-right  { text-align: right; }
.ps-tpp-print-header-accession { font-size: 12px; font-weight: 700; color: #e2e8f0; }
.ps-tpp-print-header-patient   { font-size: 11px; color: #94a3b8; }
.ps-tpp-print-footer { display: flex; justify-content: space-between; align-items: center;
  padding-top: 6px; margin-top: 10px; border-top: 1px solid #e2e8f0; font-size: 9px; color: #64748b; }
.ps-tpp-template-ref { padding: 6px 10px; background: #eff6ff; border: 1px dashed #93c5fd;
  border-radius: 4px; font-size: 10px; color: #3b82f6; }

/* ── Ruler ────────────────────────────────────────────────────── */
.ps-tpp-ruler-wrap { margin-bottom: 8px; }
.ps-tpp-ruler { height: 20px; background: #f1f5f9; border-bottom: 1px solid #e2e8f0; position: relative;
  flex-shrink: 0; }
.ps-tpp-ruler-tick { position: absolute; display: flex; flex-direction: column; align-items: center; }
.ps-tpp-ruler-tick-bar { width: 1px; height: 4px; background: #94a3b8; }
.ps-tpp-ruler-tick-bar--major { height: 8px; }
.ps-tpp-ruler-tick-label { font-size: 8px; color: #64748b; margin-top: 1px; }
.ps-tpp-ruler-margin { position: absolute; top: 0; height: 100%; background: rgba(8,145,178,0.06); }
.ps-tpp-ruler-margin--left  { left: 0; border-right: 1px dashed #bae6fd; }
.ps-tpp-ruler-margin--right { right: 0; border-left: 1px dashed #bae6fd; }

/* ── Page card (the printed document page) ───────────────────── */
.ps-tpp-page-card { background: #fff; border-radius: 2px; box-shadow: 0 2px 8px rgba(0,0,0,0.18),
  0 0 0 1px rgba(0,0,0,0.06); position: relative; display: flex; flex-direction: column;
  font-family: 'Georgia','Times New Roman',serif; }
.ps-tpp-page-num  { position: absolute; top: -22px; right: 0; font-size: 10px; color: #9ca3af;
  letter-spacing: 0.04em; }
.ps-tpp-page-body { flex: 1; }
.ps-tpp-page-wrap  { margin-bottom: 28px; position: relative; }

/* ── Overlay / toolbar / panels (fixed dark chrome) ──────────── */
.ps-tpp-overlay { position: fixed; inset: 0; z-index: 1000; display: flex; flex-direction: column;
  overflow: hidden; background: #374151; font-family: 'Inter','Segoe UI',system-ui,sans-serif; }

.ps-tpp-toolbar { display: flex; align-items: center; gap: 12px; padding: 0 20px; height: 48px;
  background: #1f2937; border-bottom: 1px solid #374151; flex-shrink: 0; }
.ps-tpp-toolbar-select { background: #374151; border: 1px solid #4b5563; color: #f9fafb; border-radius: 6px;
  padding: 4px 8px; font-size: 12px; cursor: pointer; font-family: inherit; }
.ps-tpp-toolbar-dim    { font-size: 11px; color: #9ca3af; }
.ps-tpp-toolbar-spacer { flex: 1; }
.ps-tpp-toolbar-btn    { background: #374151; border: 1px solid #4b5563; color: #d1d5db; border-radius: 6px;
  padding: 5px 12px; font-size: 11px; cursor: pointer; font-family: inherit; }
.ps-tpp-toolbar-btn:hover { background: #4b5563; }
.ps-tpp-toolbar-btn--close { background: #0891b2; border: none; color: #fff; padding: 5px 14px;
  font-size: 12px; font-weight: 600; }
.ps-tpp-toolbar-btn--close:hover { background: #07748f; }

.ps-tpp-margins-panel { background: #1f2937; border-bottom: 1px solid #374151; padding: 10px 20px;
  display: flex; gap: 20px; align-items: center; flex-shrink: 0; }
.ps-tpp-margins-label { font-size: 11px; color: #9ca3af; font-weight: 600; }
.ps-tpp-margin-field  { display: flex; align-items: center; gap: 6px; font-size: 11px; color: #d1d5db; }
.ps-tpp-margin-input  { width: 48px; background: #374151; border: 1px solid #4b5563; color: #f9fafb;
  border-radius: 4px; padding: 3px 6px; font-size: 11px; font-family: inherit; }

.ps-tpp-ctx-panel { background: #111827; border-bottom: 1px solid #374151; padding: 12px 20px;
  max-height: 200px; overflow-y: auto; flex-shrink: 0; }
.ps-tpp-ctx-title { font-size: 10px; font-weight: 700; color: #94a3b8; margin-bottom: 6px;
  text-transform: uppercase; letter-spacing: 0.06em; }
.ps-tpp-ctx-json  { font-size: 9px; color: #9ca3af; margin: 0; white-space: pre-wrap; }

.ps-tpp-doc-area { flex: 1; overflow-y: auto; padding: 24px 40px; display: flex; flex-direction: column;
  align-items: center; }
.ps-tpp-measure-root { position: fixed; left: -9999px; top: 0; visibility: hidden; pointer-events: none;
  z-index: -1; }
.ps-tpp-doc-bottom-spacer { height: 48px; }

/* ── Routing Rules: matched-pass indicator (Test Routing panel) ── */
.ps-rr-priority-row--matched { background: rgba(16,185,129,0.08); border-radius: 5px;
  margin: 0 -8px; padding: 3px 8px; }
.ps-rr-priority-row--matched .ps-rr-priority-result { color: #34d399; font-weight: 600; }
.ps-rr-priority-row--unreached { opacity: 0.4; }
.ps-rr-priority-row--unreached .ps-rr-priority-result { font-style: italic; }
.ps-rr-priority-check { font-size: 13px; font-weight: 700; color: #10b981; flex-shrink: 0; }

/* ============================================================
   ACCESSION PAGE (Stage 0 — Orchestration Workflow)
   ============================================================ */

.ps-accession-shell {
  height: 100%;
  /* Real, per direct UI-review follow-up ("Fix the root"):
     background-color removed — this used to hardcode
     var(--ps-navy-base), one of two, subtly different navy shades
     this app had drifted into (the other being AppShell.tsx's own,
     now-removed inline #020617). Not overriding at all now means
     this page falls through to AppShell's own real, corrected
     .ps-app-root background, the same one Configuration/Quality
     Assurance/Intraop Queue/Contribution already show — one real
     source of truth instead of pages each trying to independently
     match a moving target. */
  color: var(--ps-text-primary);
  overflow-y: auto;
}

.ps-accession-content {
  max-width: 1180px;
  margin: 0 auto;
  padding: 24px 24px 40px;
}

.ps-accession-header {
  margin-bottom: 24px;
}

.ps-accession-title {
  font-size: 22px;
  font-weight: 800;
  margin: 0;
  color: var(--ps-text);
}

.ps-accession-subtitle {
  font-size: 13px;
  color: var(--ps-text-muted);
  margin-top: 4px;
}

.ps-accession-tabs {
  margin-bottom: 20px;
}

/* Non-interactive variant of ps-card-dark — form panels, not clickable rows */
.ps-accession-card {
  cursor: default;
  padding: 20px;
}

.ps-accession-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px 16px;
}

.ps-accession-grid input,
.ps-accession-grid select,
.ps-accession-grid textarea {
  width: 100%;
}

.ps-accession-field--full {
  grid-column: 1 / -1;
}

.ps-accession-textarea {
  min-height: 70px;
  resize: vertical;
  font-family: inherit;
}

/* Real feature, per direct follow-up: "The hold Retention flag
   should be also on the accession screen." A plain checkbox toggle
   revealing two fields — see AccessionPage.tsx's own comment on why
   this stays inline rather than a modal like Case Comment/
   Deficiencies. Amber, not red — a hold is a deliberate, legitimate
   action a real person is choosing to take, not an error state (see
   ps-conf-error-text's own red, reserved for the "note required"
   validation message right below it). */
.ps-retention-hold-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  color: #F59E0B;
  cursor: pointer;
}
.ps-retention-hold-toggle input[type="checkbox"] {
  width: 16px;
  height: 16px;
  cursor: pointer;
  accent-color: #F59E0B;
}
.ps-retention-hold-fields {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 16px;
  margin-top: 12px;
  padding: 14px;
  border: 1px solid rgba(245,158,11,0.3);
  border-radius: 10px;
  background: rgba(245,158,11,0.06);
}
.ps-required-marker {
  color: #f87171;
}

.ps-accession-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 20px;
}

.ps-accession-actions--split {
  justify-content: space-between;
}

.ps-accession-specimen-row {
  cursor: default;
  padding: 16px;
  margin-bottom: 12px;
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.ps-accession-specimen-badge {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: rgba(8, 145, 178, 0.15);
  color: var(--ps-teal-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  flex-shrink: 0;
}

.ps-accession-specimen-field {
  flex: 1;
}

.ps-accession-remove-btn {
  color: #ef4444;
}

.ps-accession-add-btn {
  margin-bottom: 20px;
}

.ps-accession-summary-meta {
  font-size: 13px;
  color: var(--ps-text-muted);
}

.ps-accession-summary-list {
  font-size: 13px;
  color: var(--ps-text-muted);
  padding-left: 18px;
}

/* Stacked variant of ps-form-row for the per-specimen assignment readout */
.ps-accession-assignment-row {
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.ps-accession-assignment-head {
  display: flex;
  justify-content: space-between;
  width: 100%;
}

.ps-accession-assignment-name {
  font-size: 13px;
}

.ps-accession-assignment-meta {
  font-size: 12px;
  color: var(--ps-teal-light);
}

/* Applied instead of inline color when an assignment fell back to the
   default template (low confidence) — state drives which class is
   applied, not a raw style value. */
.ps-accession-assignment-meta--warn {
  color: #f59e0b;
}

.ps-accession-assignment-reason {
  font-size: 12px;
  color: var(--ps-text-muted);
}

.ps-accession-warnings {
  margin-top: 12px;
  padding: 10px;
  border-radius: 8px;
  background: rgba(245, 158, 11, 0.08);
  border: 1px solid rgba(245, 158, 11, 0.2);
}

.ps-accession-warning-item {
  font-size: 12px;
  color: #f59e0b;
}

/* Real fix, per direct reminder: "no business logic in the UI code
   and no inline css." Foreign-ID collision warning — deliberately its
   own class, not a reuse of ps-accession-warnings above: that class is
   amber/general-warning toned, a genuine data collision (this app's
   own foreignIdCollision.ts) is a more severe, error-toned situation,
   so it gets its own, red-toned treatment. Used by ForeignIdFields.tsx
   (and any future caller needing the identical warning). */
.ps-foreign-id-collision-warning {
  margin-bottom: 12px;
  padding: 10px;
  border-radius: 8px;
  background: rgba(248, 113, 113, 0.08);
  border: 1px solid rgba(248, 113, 113, 0.3);
}

.ps-foreign-id-collision-warning-text {
  font-size: 12px;
  color: #f87171;
  font-weight: 600;
}

/* Real fix, per direct reminder: "no business logic in the UI code
   and no inline css." Shared teal "print/reprint" action button —
   MatrixBlockEditorModal.tsx's own "Reprint Cassette Label" and
   "Print Secondary Label" buttons both used this exact same visual
   treatment as an inline style, duplicated. Modifier variants handle
   the two real size differences (header-inline vs. body-block)
   without duplicating the shared color/border/cursor rules twice. */
.ps-teal-action-btn {
  font-weight: 600;
  color: #0891B2;
  background: rgba(8, 145, 178, 0.1);
  border: 1px solid rgba(8, 145, 178, 0.3);
  border-radius: 7px;
  cursor: pointer;
}

.ps-teal-action-btn--inline {
  font-size: 11px;
  padding: 6px 10px;
  flex-shrink: 0;
  white-space: nowrap;
}

.ps-teal-action-btn--block {
  font-size: 12px;
  padding: 7px 12px;
  margin-bottom: 4px;
}

/* Real fix, per direct reminder: "no business logic in the UI code
   and no inline css." PrintSettingsSection.tsx's own real, repeated
   card-layout pattern (title/description/control, one real card per
   setting) — genuinely used by every card in that file, not invented
   for just one. */
.ps-conf-page {
  padding: 24px;
}

.ps-conf-loading {
  padding: 40px 24px;
  text-align: center;
  color: var(--ps-conf-text-3);
  font-size: 14px;
}

.ps-conf-section-subtitle--spaced {
  margin-bottom: 24px;
}

.ps-conf-card--spaced {
  margin-bottom: 12px;
}

/* AITab (Config/AI/index.tsx) — batch 160: same family, a card that
   needs the larger 24px gap the standalone AI Engine card originally
   had inline, distinct from the 12px --spaced modifier above. */
.ps-conf-card--mb24 {
  margin-bottom: 24px;
}

.ps-conf-card-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--ps-conf-text);
  margin-bottom: 4px;
}

.ps-conf-card-description {
  font-size: 13px;
  color: var(--ps-conf-text-2);
  margin-bottom: 12px;
}

.ps-conf-card-description--tight {
  font-size: 13px;
  color: var(--ps-conf-text-2);
}

.ps-conf-radio-group {
  display: flex;
  gap: 12px;
}

.ps-conf-radio-label {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.ps-conf-radio-input {
  width: 16px;
  height: 16px;
  accent-color: var(--ps-conf-teal);
}

.ps-conf-option-text {
  font-size: 14px;
  color: var(--ps-conf-text);
}

.ps-conf-toggle-label-row {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  flex-shrink: 0;
}

.ps-conf-select-wide {
  max-width: 420px;
}

.ps-conf-input-code {
  width: 120px;
  text-align: center;
}

.ps-conf-input-gtin {
  width: 220px;
}

.ps-conf-prefix-row {
  display: flex;
  gap: 16px;
}

.ps-conf-prefix-field-label {
  display: block;
  font-size: 12px;
  color: var(--ps-conf-text-3);
  margin-bottom: 4px;
}

.ps-conf-container-type-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 8px;
}

.ps-conf-container-type-label {
  font-size: 13px;
  color: var(--ps-conf-text);
  flex: 1;
}

.ps-conf-saving-indicator {
  font-size: 12px;
  color: var(--ps-conf-text-3);
  margin-top: 8px;
}

/* Real feature, per direct follow-up: cell blocks "frequently use
   distinct cassette colors... to signal fragile cytopreparations to
   histotechnologists." Real, justified exception to "no inline css":
   the swatch's own background color is genuinely dynamic, admin-
   configured data (CassetteColorDefinition.hexCode) — matching this
   app's own, already-established pattern for the identical problem
   in CassetteColorsSection.tsx's own table. Every FIXED property
   (size, shape, border) lives here; only the truly dynamic color
   value stays as an inline style at the real call site. */
.ps-cassette-color-control {
  margin-bottom: 16px;
}

.ps-cassette-color-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.ps-cassette-color-swatch {
  display: inline-block;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.2);
  flex-shrink: 0;
  /* PS-73 (Sep 2026): reads the real, per-row --swatch-color custom
     property CassetteColorsSection.tsx sets inline — same indirection
     already used by .ps-type-color-swatch/.ps-del-id-badge above for the
     identical real need (a value that's genuinely per-instance, not
     expressible as a static class). */
  background: var(--swatch-color);
}

.ps-cassette-color-name {
  font-size: 13px;
  color: var(--ps-conf-text, #e2e8f0);
}

