/* ── CoPilot Report View (print) ─────────────────────────────────────── */
.ps-copilot-report-view { background: #0b1120; color: #e2e8f0; width: 90vw; max-width: 900px; max-height: 90vh; overflow-y: auto; border-radius: 12px; border: 1px solid #1e293b; margin: 5vh auto; }
.ps-copilot-report-view-toolbar { position: sticky; top: 0; display: flex; justify-content: space-between; align-items: center; padding: 14px 20px; background: #0f172a; border-bottom: 1px solid #1e293b; z-index: 1; }
