/* ═══════════════════════════════════════════════════════════════════════
   SynopticReportPage.tsx — full inline-style cleanup.
   Every rule below reproduces the exact values the removed inline style
   objects had; this is a like-for-like conversion, not a redesign.
   ═══════════════════════════════════════════════════════════════════════ */

@keyframes ps-spin { to { transform: rotate(360deg); } }

/* App.tsx — the top-level route Suspense fallback spinner, reusing the
   ps-spin keyframe just above (a local <style> tag in App.tsx used to
   redefine this same keyframe on every render — real, redundant CSS,
   removed in favor of this). */
.ps-app-loader-overlay {
  position: fixed; inset: 0; background: #0b1120;
  display: flex; align-items: center; justify-content: center;
  z-index: 10000;
}
.ps-app-loader-spinner {
  width: 36px; height: 36px;
  border: 3px solid rgba(8,145,178,0.15);
  border-top: 3px solid #0891B2;
  border-radius: 50%;
  animation: ps-spin 0.7s linear infinite;
}

/* Case not found screen */
.ps-case-not-found { position: fixed; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #0b1120; gap: 16px; padding-top: 88px; box-sizing: border-box; }
.ps-case-not-found-icon { font-size: 48px; }
.ps-case-not-found-title { font-size: 20px; font-weight: 700; color: #e2e8f0; }
.ps-case-not-found-subtitle { font-size: 14px; color: #64748b; }
.ps-case-not-found-id { color: #38bdf8; }
.ps-case-not-found-button { margin-top: 8px; }

/* Root shell */
.ps-synrp-root {
  position: relative; width: 100vw; height: var(--app-height, 100vh);
  background-color: #0f172a; color: #fff; font-family: 'Inter', sans-serif;
  display: flex; flex-direction: column; overflow: hidden;
  opacity: 0; transition: opacity 0.4s ease;
}
.ps-synrp-root--loaded { opacity: 1; }
.ps-synrp-bg-image { position: absolute; inset: 0; background-image: url(/main_background.jpg); background-size: cover; background-position: center; z-index: 0; }
.ps-synrp-bg-overlay { position: absolute; inset: 0; background: rgba(0,0,0,0.72); z-index: 1; }
.ps-synrp-bg-gradient { position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(0,0,0,0.4) 0%, rgba(0,0,0,0.75) 100%); z-index: 2; }
.ps-synrp-shell { position: relative; z-index: 10; display: flex; flex-direction: column; height: 100%; }

/* Auto-generate toast */
.ps-autogen-toast {
  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
  z-index: 10000; display: flex; align-items: center; gap: 14px;
  background: #1e293b; border: 1px solid rgba(8,145,178,0.4);
  border-radius: 10px; padding: 12px 16px; box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}
.ps-autogen-toast-spinner { display: inline-flex; width: 16px; height: 16px; border-radius: 50%; border: 2px solid rgba(56,189,248,0.3); border-top-color: #38bdf8; animation: ps-spin 0.8s linear infinite; }
.ps-autogen-toast-text { font-size: 13px; color: #e2e8f0; }
.ps-autogen-toast-cancel { padding: 5px 12px; font-size: 12px; font-weight: 600; background: rgba(148,163,184,0.1); border: 1px solid rgba(148,163,184,0.3); border-radius: 6px; color: #cbd5e1; cursor: pointer; font-family: inherit; }

/* Alert banner */
.ps-alert-banner { background: #fef3c7; border-top: none; border-bottom: 1px solid #fde047; flex-shrink: 0; }
.ps-alert-banner-row { display: flex; justify-content: space-between; align-items: center; padding: 5px 40px; cursor: pointer; user-select: none; }
.ps-alert-banner-text { display: flex; align-items: center; gap: 8px; font-weight: 600; color: #92400e; font-size: 12px; }
.ps-alert-banner-link { text-decoration: underline; font-weight: 700; }
.ps-alert-chevron { font-size: 12px; color: #92400e; transform: none; transition: transform 0.2s; cursor: pointer; }
.ps-alert-chevron--expanded { transform: rotate(180deg); }
.ps-alert-banner-detail { padding: 0 40px 6px; color: #78350f; font-size: 11px; border-top: 1px solid #fde047; padding-top: 5px; }

/* Main body / left panel */
.ps-synrp-main-body { flex: 1; display: flex; min-height: 0; overflow: hidden; }
.ps-syn-left-panel-wrap { flex: 1; min-width: 0; overflow: hidden; position: relative; background: rgba(15,23,42,0.95); display: flex; flex-direction: column; }
.ps-syn-nav-strip-empty { color: #94a3b8; }

/* Tab bar (used in both the normal view and the full-screen sequencer overlay) */
.ps-syn-tabbar { display: flex; align-items: center; border-bottom: 1px solid rgba(255,255,255,0.08); flex-shrink: 0; background: rgba(10,16,32,0.6); overflow-x: auto; overflow-y: hidden; }
.ps-syn-tab-btn {
  padding: 9px 18px; font-size: 12px; font-weight: 400; color: rgba(148,163,184,0.7);
  background: none; border: none; border-bottom: 2px solid transparent;
  cursor: pointer; transition: all 0.15s; display: flex; align-items: center; gap: 6px;
  white-space: nowrap;
}
.ps-syn-tab-btn:not(.ps-syn-tab-btn--active):hover { color: #94a3b8; }
.ps-syn-tab-btn--active { font-weight: 600; color: #38bdf8; border-bottom: 2px solid #38bdf8; }
.ps-syn-tab-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
.ps-syn-tab-dot--finalized   { background: #10b981; border: 1.5px solid #10b981; box-shadow: 0 0 5px #10b981; }
.ps-syn-tab-dot--pending     { background: #f59e0b; border: 1.5px solid #f59e0b; box-shadow: 0 0 5px #f59e0b; }
.ps-syn-tab-dot--in-progress { background: #60a5fa; border: 1.5px solid #60a5fa; box-shadow: 0 0 5px #60a5fa; }
.ps-syn-tab-dot--draft       { background: #3b82f6; border: 1.5px solid #3b82f6; box-shadow: 0 0 5px #3b82f6; }

/* Real fix, per direct follow-up with a screenshot: "The buttons top
   and bottom just go under the other objects and are not reachable."
   Confirmed directly, live: at a genuinely narrow+short window, this
   row's own content (tabs + tools) exceeds the tabbar's real,
   available width, and without this, the tools section rendered
   underneath the adjacent right pane's own header — not just
   scrolled off, genuinely covered by another pane's content
   (confirmed via a direct elementFromPoint() check at the exact
   pixel). Sticky-right keeps Dev Tools/Sequencer permanently in
   view regardless of horizontal scroll position, so a tech never
   needs to discover that this row scrolls at all — the tabs
   themselves scroll underneath, the tools never do. A real,
   opaque background (matching the tabbar's own) is required for
   this to work correctly — without one, scrolled-under tab content
   would show through the sticky tools' own transparent gaps. */
.ps-syn-tabbar-tools { margin-left: auto; padding: 0 10px; display: flex; align-items: center; gap: 8px; position: sticky; right: 0; background: #0d1420; flex-shrink: 0; z-index: 2; }
.ps-syn-dev-btn { font-size: 11px; padding: 4px 10px; border-radius: 5px; cursor: pointer; font-weight: 600; white-space: nowrap; }
.ps-syn-dev-btn--microscopic { background: rgba(245,158,11,0.12); border: 1px solid rgba(245,158,11,0.35); color: #f59e0b; }
.ps-syn-dev-btn--lis { background: rgba(217,119,6,0.12); border: 1px solid rgba(217,119,6,0.35); color: #d97706; }
/* Real fix, per direct follow-up: "we are not displaying all the
   available buttons in the synoptic report page." Confirmed directly,
   live: 3 real dev-only Sim buttons + Sequencer genuinely overflowed
   the tabbar's real, available width — the last button(s) were
   visually clipped at the panel boundary. One, fixed-width dropdown
   trigger replaces all 3 individual Sim buttons — the row's own
   width no longer grows every time another simulation is added. */
.ps-syn-devmenu-wrap { position: relative; }
.ps-syn-devmenu {
  position: absolute; top: calc(100% + 4px); left: 0; z-index: 500;
  background: #0f1729; border: 1px solid rgba(245,158,11,0.35); border-radius: 8px;
  padding: 4px; display: flex; flex-direction: column; gap: 2px; min-width: 220px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}
/* Real fix, per direct report: "Dev Tools items are hidden behind the
   left pane." A real regression from this same app's own earlier fix —
   .ps-syn-tabbar (this dropdown's CSS ancestor before this change)
   picked up overflow-y: hidden to stop the tabbar's own content
   bleeding horizontally into the adjacent pane, which also silently
   clipped this dropdown the moment it extended past the tabbar's own
   short height. Now portaled to document.body (SynopticReportPage.tsx's
   own devToolsBtnRef/devToolsMenuPos), so position: fixed (not
   absolute — a portaled element has no positioned ancestor to be
   "absolute" relative to) with top/left set inline from the trigger
   button's own real, measured screen position at open time. */
.ps-syn-devmenu--portaled { position: fixed; top: var(--devmenu-top, auto); left: var(--devmenu-left, auto); }
.ps-syn-devmenu-item {
  text-align: left; font-size: 12px; font-weight: 600; padding: 7px 10px; border-radius: 5px;
  background: none; border: none; cursor: pointer; color: #f59e0b; white-space: nowrap;
}
.ps-syn-devmenu-item:hover { background: rgba(245,158,11,0.12); }
.ps-syn-sequencer-btn {
  padding: 5px 12px; font-size: 11px; font-weight: 600; color: #38bdf8; cursor: pointer;
  background: rgba(8,145,178,0.1); border: 1px solid rgba(8,145,178,0.3);
  border-radius: 6px; display: flex; align-items: center; gap: 6px;
  transition: all 0.15s; white-space: nowrap;
}
.ps-syn-sequencer-btn:hover { background: rgba(8,145,178,0.2); border-color: #0891B2; }

/* Tab content panels */
.ps-syn-tab-content { flex: 1; min-height: 0; overflow: hidden; position: relative; }
.ps-syn-tab-panel { position: absolute; inset: 0; display: none; }
.ps-syn-tab-panel--dark { background: #0b1120; }
.ps-syn-tab-panel--scroll { overflow-y: auto; }
.ps-syn-tab-panel--column { flex-direction: column; }
.ps-syn-tab-panel--visible-flex { display: flex; }
.ps-syn-tab-panel--visible-block { display: block; }

/* Expand/collapse button */
.ps-syn-expand-btn-wrap { position: relative; width: 0; z-index: 200; display: flex; align-items: center; }
.ps-syn-expand-btn-wrap--hidden { display: none; }
.ps-syn-expand-btn {
  position: absolute; left: -16px; width: 32px; height: 32px; border-radius: 50%;
  background: #0891B2; border: 2px solid rgba(255,255,255,0.2); color: white;
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  font-size: 15px; box-shadow: 0 2px 12px rgba(0,0,0,0.8); transition: background 0.15s;
}
.ps-syn-expand-btn:hover { background: #0e7490; }

/* Right panel */
.ps-syn-right-panel { flex: 1; min-width: 0; background: rgba(15,23,42,0.95); display: flex; flex-direction: column; overflow: hidden; visibility: visible; }
.ps-syn-right-panel--collapsed { flex: 0 0 0px; visibility: hidden; }
.ps-syn-right-panel-scroll { flex: 1; min-height: 0; overflow-y: auto; }
.ps-syn-right-panel-scroll--flex { min-width: 0; background: rgba(15,23,42,0.95); }

/* Full-screen sequencer overlay */
.ps-syn-sequencer-overlay { position: fixed; inset: 0; z-index: 9000; display: flex; flex-direction: column; background: #0a0f1e; }
.ps-syn-sequencer-header { background: rgba(8,20,40,0.98); border-bottom: 1px solid rgba(8,145,178,0.3); flex-shrink: 0; }
.ps-syn-sequencer-header-row { display: flex; align-items: center; gap: 10px; padding: 0 20px; height: 34px; font-size: 12px; }
.ps-syn-sequencer-accession { font-weight: 700; color: #38bdf8; font-family: monospace; }
.ps-syn-sequencer-sep { color: #94a3b8; }
.ps-syn-sequencer-patient { color: #f1f5f9; font-weight: 600; }
.ps-syn-sequencer-value { color: #f1f5f9; }
.ps-syn-sequencer-value--spaced { margin-left: 3px; }
.ps-syn-sequencer-label { color: #94a3b8; font-size: 11px; }
.ps-syn-sequencer-specimen-row { display: flex; align-items: center; gap: 12px; padding: 0 20px 10px; overflow-x: auto; }
.ps-syn-sequencer-specimen-label { font-size: 10px; color: #94a3b8; font-weight: 700; letter-spacing: 0.08em; flex-shrink: 0; text-transform: uppercase; margin-right: 4px; }
.ps-syn-sequencer-specimen-item { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }
.ps-syn-sequencer-warn-icon { font-size: 10px; }
.ps-syn-sequencer-body { flex: 1; display: flex; min-height: 0; }
.ps-syn-sequencer-left-col { flex: 1; min-width: 0; overflow: hidden; display: flex; flex-direction: column; background: rgba(15,23,42,0.95); }

/* Specimen pill state variants — base .ps-specimen-pill / .warning already
   exist elsewhere; these add only the per-state color logic that used to
   be computed inline (hasNone × isActive, 3 real states). */
.ps-specimen-pill--warning  { border: 1.5px solid #d97706; background: transparent; color: #fbbf24; }
.ps-specimen-pill--active   { border: 1.5px solid #0891B2; background: #0891B2; color: #ffffff; }
.ps-specimen-pill--inactive { border: 1.5px solid #0891B2; background: transparent; color: #7dd3fc; }
.ps-specimen-pill-letter { font-weight: 800; }
.ps-specimen-pill--warning .ps-specimen-pill-letter  { color: #f59e0b; }
.ps-specimen-pill--active .ps-specimen-pill-letter   { color: #ffffff; }
.ps-specimen-pill--inactive .ps-specimen-pill-letter { color: #38bdf8; }
.ps-specimen-pill-select {
  height: 24px; font-size: 11px; font-weight: 600; max-width: 160px; flex-shrink: 0;
  background: rgba(8,145,178,0.15); color: #7dd3fc; border: 1.5px solid #0891B2;
  border-radius: 20px; padding: 0 8px; cursor: pointer; outline: none;
}

/* Tab-switch unsaved-draft confirmation modal */
.ps-tabswitch-overlay { position: fixed; inset: 0; z-index: 9500; background: rgba(0,0,0,0.7); display: flex; align-items: center; justify-content: center; padding-top: 88px; padding-bottom: 32px; box-sizing: border-box; overflow-y: auto; }
.ps-tabswitch-modal { background: #1e293b; border: 1px solid rgba(148,163,184,0.2); border-radius: 12px; padding: 28px 32px; max-width: 420px; width: 90%; }
.ps-tabswitch-title { font-size: 16px; font-weight: 700; color: #e2e8f0; margin-bottom: 8px; }
.ps-tabswitch-body { font-size: 13px; color: #94a3b8; margin-bottom: 24px; line-height: 1.6; }
.ps-tabswitch-footer { display: flex; gap: 10px; justify-content: flex-end; }
.ps-tabswitch-btn { padding: 8px 16px; border-radius: 6px; font-size: 12px; cursor: pointer; font-family: inherit; }
.ps-tabswitch-btn--cancel  { background: transparent; border: 1px solid rgba(148,163,184,0.2); color: #64748b; }
.ps-tabswitch-btn--discard { background: rgba(148,163,184,0.1); border: 1px solid rgba(148,163,184,0.2); color: #cbd5e1; }
.ps-tabswitch-btn--save    { background: rgba(8,145,178,0.2); border: 1px solid rgba(8,145,178,0.4); color: #38bdf8; font-weight: 600; }

/* Persistent physician contact card — visible without opening the
   search dropdown, for whoever's currently set in the field. */
.ps-amendment-physician-selected-card {
  display: flex; flex-direction: row; align-items: flex-start; gap: 12px;
  margin-top: 8px; padding: 10px 14px;
  background: #1e293b; border: 1px solid #334155; border-radius: 8px;
}
.ps-amendment-physician-selected-card .ps-amendment-physician-avatar { flex-shrink: 0; }
.ps-amendment-physician-selected-card .ps-amendment-physician-info {
  display: flex; flex-direction: column; gap: 4px; padding-top: 2px;
}
.ps-amendment-physician-selected-card .ps-amendment-physician-specialty { color: #94a3b8; font-size: 0.85em; }
.ps-amendment-physician-selected-card .ps-amendment-physician-contact {
  display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 2px; font-size: 0.82em;
}

/* Pre-finalisation preview — section headers within each synoptic report */
.ps-prefin-preview-section { margin-bottom: 14px; }
.ps-prefin-preview-section-title {
  font-size: 10px; font-weight: 800; color: #0891B2; letter-spacing: 0.08em;
  text-transform: uppercase; margin-bottom: 6px; padding-bottom: 4px;
  border-bottom: 1px solid rgba(8,145,178,0.25);
}

/* Amendment diff table — collapse toggle + section grouping */
.ps-amendment-narrative-header-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.ps-amendment-collapse-toggle {
  background: none; border: none; color: #fdba74; font-size: 0.82em; font-weight: 600;
  cursor: pointer; padding: 2px 8px; white-space: nowrap;
}
.ps-amendment-matrix-section-row td {
  font-size: 10px; font-weight: 800; color: #fdba74; letter-spacing: 0.08em;
  text-transform: uppercase; padding-top: 12px; padding-bottom: 4px;
  border-bottom: 1px solid rgba(253,186,116,0.25);
}

/* Copilot print/report-view modal — real two-pane layout */
.ps-overlay--copilot-report { z-index: 9000; }
.ps-copilot-report-view--two-pane { display: flex; flex-direction: column; width: 95vw; max-width: 1400px; height: 90vh; max-height: 900px; }
.ps-copilot-report-body-split { flex: 1; display: flex; min-height: 0; }

.ps-copilot-report-left {
  width: 420px; flex-shrink: 0; overflow-y: auto; padding: 16px;
  background: #0f172a; border-right: 1px solid #334155;
}
.ps-copilot-report-left-hint { color: #64748b; font-size: 0.85em; margin-top: 12px; line-height: 1.5; }
.ps-copilot-report-specimen-card {
  margin-bottom: 16px; padding: 12px; background: #1e293b; border: 1px solid #334155; border-radius: 8px;
}
.ps-copilot-report-specimen-header { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
.ps-copilot-report-specimen-num {
  flex-shrink: 0; width: 26px; height: 26px; border-radius: 50%; background: #0891B2; color: #fff;
  display: flex; align-items: center; justify-content: center; font-size: 0.85em; font-weight: 700;
}
.ps-copilot-report-specimen-name { color: #e2e8f0; font-weight: 600; font-size: 1.02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ps-copilot-report-specimen-count { color: #94a3b8; font-size: 0.85em; }
.ps-copilot-report-instance-block { margin-left: 36px; margin-bottom: 8px; }
.ps-copilot-report-instance-row {
  display: block; width: 100%; text-align: left; padding: 6px 8px; font-family: inherit;
  background: none; border: none; border-radius: 6px; color: #cbd5e1; font-size: 0.95em; font-weight: 600;
  cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.ps-copilot-report-instance-row:hover { background: rgba(148,163,184,0.08); }
.ps-copilot-report-instance-row--active { color: #38bdf8; }

.ps-copilot-report-version-row {
  display: flex; align-items: center; gap: 8px; width: 100%; padding: 6px 8px 6px 16px;
  background: none; border: 1px solid transparent; border-radius: 6px;
  cursor: pointer; text-align: left; font-family: inherit;
}
.ps-copilot-report-version-row:hover { background: rgba(148,163,184,0.08); }
.ps-copilot-report-version-row--active { border-color: #0891B2; background: rgba(8,145,178,0.12); }
.ps-copilot-report-version-badge {
  flex-shrink: 0; font-size: 11px; font-weight: 800; color: #38bdf8;
  background: rgba(56,189,248,0.15); border-radius: 4px; padding: 2px 6px;
}
.ps-copilot-report-version-label { color: #e2e8f0; font-size: 0.88em; font-weight: 600; white-space: nowrap; }
.ps-copilot-report-section-version-tag {
  margin-left: 10px; font-size: 0.7em; font-weight: 700; color: #38bdf8;
  background: rgba(56,189,248,0.15); border-radius: 4px; padding: 2px 8px; vertical-align: middle;
}

.ps-copilot-report-right { flex: 1; min-width: 0; overflow-y: auto; }

.ps-copilot-report-version-meta { color: #94a3b8; font-size: 0.78em; margin-left: auto; }

/* Amendment narrative + Originally Reported As diff in the print output */
.ps-copilot-report-amendment-narrative {
  background: rgba(217,119,6,0.08); border: 1px solid rgba(217,119,6,0.35); border-radius: 8px;
  padding: 10px 14px; margin-bottom: 12px; font-size: 12px; line-height: 1.6;
}
.ps-copilot-report-amendment-flag { font-size: 10px; font-weight: 800; color: #d97706; letter-spacing: 0.08em; margin-bottom: 4px; }
.ps-copilot-report-diff-table { margin-bottom: 14px; }
.ps-copilot-report-diff-table th { text-align: left; font-size: 10px; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.06em; padding-bottom: 6px; border-bottom: 1px solid #334155; }
.ps-copilot-report-diff-previous { color: #94a3b8; text-decoration: line-through; }
.ps-copilot-report-diff-current { color: #38bdf8; font-weight: 600; }

@media print {
  .ps-copilot-report-amendment-narrative { background: #fff7ed; border-color: #d97706; color: #000; }
  .ps-copilot-report-amendment-flag { color: #d97706; }
  .ps-copilot-report-diff-previous { color: #666; }
  .ps-copilot-report-diff-current { color: #000; }
}

/* ── Case Team Modal (CaseTeamModal.tsx) — extracted from inline styles ──── */

.ps-ctm-staff-card {
  padding: 10px 12px;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  cursor: grab;
  user-select: none;
  touch-action: none;
  transition: border-color 0.15s;
}
.ps-ctm-staff-card--dragging { background: rgba(138,180,248,0.15); border-color: rgba(138,180,248,0.4); transition: none; }
.ps-ctm-staff-card--disabled { cursor: default; opacity: 0.4; }

.ps-ctm-staff-row { display: flex; align-items: center; gap: 10px; }

.ps-ctm-staff-avatar {
  width: 32px; height: 32px; border-radius: 50%; flex-shrink: 0;
  background: rgba(138,180,248,0.15); border: 1.5px solid rgba(138,180,248,0.3);
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 700; color: #8AB4F8;
}

.ps-ctm-staff-info { flex: 1; min-width: 0; }
.ps-ctm-staff-name { font-size: 13px; font-weight: 600; color: #e5e7eb; }
.ps-ctm-staff-meta  { font-size: 11px; color: #cbd5e1; }

.ps-ctm-staff-grip { font-size: 16px; color: #374151; flex-shrink: 0; cursor: grab; }

.ps-ctm-staff-oncase-badge {
  font-size: 10px; color: #22c55e; padding: 1px 6px; border-radius: 4px;
  border: 1px solid rgba(34,197,94,0.2); background: rgba(34,197,94,0.06); flex-shrink: 0;
}

.ps-ctm-staff-badges { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 6px; }
/* --badge-bg / --badge-border / --badge-color set inline per-item from the
   participation type's own color field — genuinely dynamic per-record data,
   pre-computed in the component using this app's existing hex+alpha-suffix
   convention (t.color + '18' etc, same as used throughout the rest of the
   app), not a new pattern introduced here. */
.ps-ctm-staff-badge {
  font-size: 10px; padding: 1px 6px; border-radius: 10px;
  background: var(--badge-bg); color: var(--badge-color); border: 1px solid var(--badge-border);
}

/* Drop zones — three live-preview eligibility states, set during drag */
.ps-ctm-dropzone {
  border-radius: 10px; padding: 12px; min-height: 80px;
  transition: all 0.15s;
  background: rgba(255,255,255,0.02);
  border: 2px dashed rgba(255,255,255,0.08);
}
.ps-ctm-dropzone--role-ineligible { border-color: rgba(239,68,68,0.35); background: rgba(239,68,68,0.04); cursor: not-allowed; }
.ps-ctm-dropzone--role-ineligible.ps-ctm-dropzone--hover { border-color: rgba(239,68,68,0.6); background: rgba(239,68,68,0.1); }
.ps-ctm-dropzone--occupied { border-color: rgba(245,158,11,0.35); background: rgba(245,158,11,0.04); }
.ps-ctm-dropzone--occupied.ps-ctm-dropzone--hover { border-style: solid; border-color: rgba(245,158,11,0.6); background: rgba(245,158,11,0.1); }
.ps-ctm-dropzone--eligible { border-color: rgba(255,255,255,0.14); }
.ps-ctm-dropzone--eligible.ps-ctm-dropzone--hover {
  border-style: solid;
  border-color: var(--badge-border-strong);
  background: var(--badge-bg);
}

.ps-ctm-dropzone-header { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.ps-ctm-dropzone-type-badge {
  display: inline-block; padding: 2px 10px; border-radius: 20px; font-size: 11px; font-weight: 700;
  background: var(--badge-bg); color: var(--badge-color); border: 1px solid var(--badge-border);
}
.ps-ctm-dropzone-label { font-size: 12px; font-weight: 600; color: #e5e7eb; flex: 1; }
.ps-ctm-dropzone-single-badge { font-size: 9px; font-weight: 700; color: #64748b; letter-spacing: 0.04em; }
.ps-ctm-dropzone-countersign-badge {
  font-size: 10px; color: #f59e0b; padding: 1px 5px; border-radius: 4px;
  border: 1px solid rgba(245,158,11,0.2); background: rgba(245,158,11,0.06);
}
.ps-ctm-dropzone-finalize-badge {
  font-size: 10px; color: #22c55e; padding: 1px 5px; border-radius: 4px;
  border: 1px solid rgba(34,197,94,0.2); background: rgba(34,197,94,0.06);
}

.ps-ctm-dropzone-preview { padding: 6px 0; text-align: center; font-size: 11px; font-style: italic; }
.ps-ctm-dropzone-preview--role-ineligible { color: #f87171; }
.ps-ctm-dropzone-preview--occupied { color: #fbbf24; }
.ps-ctm-dropzone-preview--eligible { color: var(--badge-color); }

.ps-ctm-dropzone-empty { padding: 8px 0; text-align: center; font-size: 11px; color: #94a3b8; font-style: italic; }

.ps-ctm-participant-row {
  display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 8px;
  background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08);
  transition: all 0.2s;
}
.ps-ctm-participant-row--removed { background: rgba(239,68,68,0.06); border-color: rgba(239,68,68,0.2); opacity: 0.7; }

.ps-ctm-participant-avatar {
  width: 24px; height: 24px; border-radius: 50%; flex-shrink: 0;
  background: rgba(138,180,248,0.15); display: flex; align-items: center; justify-content: center;
  font-size: 9px; font-weight: 700; color: #8AB4F8;
}

.ps-ctm-participant-name { font-size: 12px; color: #e5e7eb; flex: 1; }
.ps-ctm-participant-name--removed { color: #8a9db5; text-decoration: line-through; }
.ps-ctm-participant-tag--you    { font-size: 10px; color: #8AB4F8; margin-left: 5px; }
.ps-ctm-participant-tag--auto   { font-size: 10px; color: #22c55e; margin-left: 5px; }

.ps-ctm-undo-btn {
  font-size: 10px; font-weight: 700; padding: 2px 8px; border-radius: 5px;
  border: 1px solid rgba(138,180,248,0.3); background: transparent; color: #8AB4F8; cursor: pointer;
}

.ps-ctm-delegate-btn {
  padding: 3px 6px; border-radius: 5px; border: 1px solid rgba(245,158,11,0.3);
  background: rgba(245,158,11,0.06); cursor: pointer; color: #f59e0b;
  display: flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 600;
}

.ps-ctm-remove-btn {
  padding: 3px 6px; border-radius: 5px; border: none; background: transparent;
  cursor: pointer; color: #94a3b8; display: flex; align-items: center; transition: color 0.15s;
}
.ps-ctm-remove-btn:hover { color: #f87171; }

.ps-ctm-rejection-banner {
  margin: 10px 20px 0; padding: 8px 14px; border-radius: 8px;
  background: rgba(239,68,68,0.1); border: 1px solid rgba(239,68,68,0.3);
  display: flex; align-items: center; gap: 8px; flex-shrink: 0;
}
.ps-ctm-rejection-banner-icon { font-size: 13px; }
.ps-ctm-rejection-banner-text { font-size: 12px; color: #fca5a5; flex: 1; }
.ps-ctm-rejection-banner-close { background: none; border: none; color: #fca5a5; cursor: pointer; font-size: 13px; }

.ps-ctm-drag-overlay {
  padding: 10px 14px; background: #1e293b; border: 2px solid #8AB4F8; border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4); cursor: grabbing; opacity: 0.95;
}

