.ps-ctm-dropzone-empty-hint { text-align: center; padding: 8px 0; font-style: italic; }

.ps-ctm-modal { width: 100%; max-width: 960px; height: 88vh; }

.ps-ctm-types-eyebrow { margin-bottom: 4px; }
.ps-ctm-staffdir-eyebrow { margin-bottom: 8px; }
.ps-ctm-staffdir-head { padding: 16px 16px 10px; flex-shrink: 0; }
