.ps-ctm-save-btn { font-weight: 700; }
.ps-ctm-save-btn--dirty { background: rgba(34,197,94,0.15); border-color: rgba(34,197,94,0.5); color: #4ade80; }
.ps-ctm-save-btn--saving { opacity: 0.6; }
.ps-ctm-save-btn:disabled { cursor: default; }

/* ── Custom Dropdown (components/Common/Dropdown.tsx) ─────────────────────
   Replaces native <select> where its open option list rendering natively
   (OS-controlled, not CSS-restylable) looked inconsistent with the app's
   dark theme. Matches .ps-conf-select's visual language for the closed
   trigger, but this component controls the open list itself. ────────── */

.ps-dropdown { position: relative; width: 100%; }

.ps-dropdown-trigger {
  width: 100%;
  display: flex; align-items: center; justify-content: space-between;
  background: var(--ps-conf-surface);
  border: 1px solid var(--ps-conf-border);
  border-radius: 7px;
  padding: 9px 12px;
  font-size: 13px;
  color: var(--ps-conf-text);
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  transition: border-color 0.15s;
}
.ps-dropdown-trigger:hover { border-color: var(--ps-conf-teal); }

.ps-dropdown-placeholder { color: #64748b; }

.ps-dropdown-chevron { color: #64748b; transition: transform 0.15s; flex-shrink: 0; }
.ps-dropdown-chevron--open { transform: rotate(180deg); }

.ps-dropdown-list {
  position: absolute; top: calc(100% + 4px); left: 0; right: 0;
  background: #0f172a;
  border: 1px solid var(--ps-conf-border);
  border-radius: 8px;
  box-shadow: 0 12px 32px rgba(0,0,0,0.5);
  max-height: 240px; overflow-y: auto;
  z-index: 100;
}

.ps-dropdown-option {
  padding: 9px 12px;
  font-size: 13px;
  color: var(--ps-conf-text);
  cursor: pointer;
  transition: background 0.1s;
}
.ps-dropdown-option:hover { background: rgba(255,255,255,0.06); }

.ps-dropdown-empty {
  padding: 12px; font-size: 12px; color: #94a3b8; text-align: center;
}

/* ── SearchableCombobox — extends the Dropdown styling above with a
   real filter input and keyboard-highlight state. See
   components/Common/SearchableCombobox.tsx. ── */
.ps-combobox { position: relative; width: 100%; }

.ps-combobox-selected-label { color: var(--ps-conf-text); }

.ps-combobox-list { display: flex; flex-direction: column; max-height: 280px; }

.ps-combobox-search-wrap {
  padding: 6px; border-bottom: 1px solid var(--ps-conf-border); flex-shrink: 0;
}
.ps-combobox-search-input {
