  background: var(--ps-conf-surface);
  border: 1px solid var(--ps-conf-border);
  border-radius: 6px;
  padding: 6px 9px;
  font-size: 12px;
  color: var(--ps-conf-text);
  font-family: 'Inter', sans-serif;
  outline: none;
}
.ps-combobox-search-input:focus { border-color: var(--ps-conf-teal); }

.ps-combobox-option { display: flex; flex-direction: column; gap: 1px; }
.ps-combobox-option--highlighted { background: rgba(255,255,255,0.06); }
.ps-combobox-option--selected { color: var(--ps-conf-teal); font-weight: 600; }
.ps-combobox-option-sublabel { font-size: 11px; color: #64748b; font-weight: 400; }

.ps-patient-info-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  background: rgba(8,145,178,0.06);
  border-radius: 8px;
  padding: 10px 16px;
  margin-bottom: 20px;
  font-size: 13px;
  border: 1px solid rgba(8,145,178,0.2);
}
.ps-patient-info-sep {
