}

.ps-searchpage-flag-grid { display: flex; flex-wrap: wrap; gap: 6px; padding: 4px 24px 20px; }
.ps-searchpage-flag-pill {
  padding: 6px 14px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 500;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.1);
  color: #94a3b8;
  transition: all 0.12s;
}
.ps-searchpage-flag-pill--selected {
  background: rgba(245,158,11,0.18);
  border-color: #f59e0b;
