}

.ps-searchpage-client-search-wrap { padding: 12px 24px 4px; }
.ps-searchpage-client-search-input {
  width: 100%;
  box-sizing: border-box;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.12);
