}

.ps-searchpage-cat-pills { display: flex; flex-wrap: wrap; gap: 5px; padding: 4px 24px 12px; border-bottom: 1px solid rgba(255,255,255,0.06); }
.ps-searchpage-cat-pill {
  flex-shrink: 0;
  cursor: pointer;
  border: none;
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
