/* Date section */
.ps-searchpage-date-header-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 5px; }
.ps-searchpage-date-shortcuts { display: flex; gap: 3px; }
.ps-searchpage-date-shortcut-btn {
  font-size: 10px;
  padding: 2px 6px;
  border-radius: 5px;
  cursor: pointer;
  font-weight: 600;
  transition: all 0.15s;
  background: rgba(8,145,178,0.08);
  border: 1px solid rgba(8,145,178,0.4);
  color: #7dd3fc;
}
.ps-searchpage-date-shortcut-btn--active {
  background: rgba(8,145,178,0.28);
  border-color: #0891B2;
  color: #f1f5f9;
}
.ps-searchpage-date-shortcut-btn--all {
  background: rgba(245,158,11,0.08);
  border-color: rgba(245,158,11,0.4);
  color: #fbbf24;
}
.ps-searchpage-date-shortcut-btn--all-active {
  background: rgba(245,158,11,0.28);
  border-color: #F59E0B;
  color: #fde68a;
}
.ps-searchpage-date-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
/* Same real grid mechanics as .ps-searchpage-date-grid above, but for
   two independent, fully-labeled fields side by side (each with its
   own real SectionLabel) rather than a shared label with From/To
   sub-labels underneath - real, per direct feedback: Type and Billing
   Type's own real option values are short enough that stacking them
   as two separate full-width rows wasted real vertical space in an
   already-tall filter sidebar. */
.ps-searchpage-inline-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.ps-searchpage-date-label { font-size: 10px; color: #94a3b8; margin-bottom: 2px; transition: color 0.15s; }
.ps-searchpage-date-label--active { color: #7dd3fc; }

/* Shared filter-sidebar utility classes — many sections repeat these */
.ps-searchpage-identifier-badge {
  position: absolute; right: 8px; top: 50%; transform: translateY(-50%);
  background: color-mix(in srgb, var(--accent, #0891B2) 13%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent, #0891B2) 40%, transparent);
  color: var(--accent, #0891B2);
  border-radius: 999px; padding: 1px 8px; font-size: 10px; font-weight: 700;
  pointer-events: none; white-space: nowrap;
}
/* Real gap, item #46: no way to clear the identifier field short of
   selecting and deleting the text manually. Sits at the same right
   edge the badge already uses; when both are present at once (a
   detected type AND text to clear), the badge shifts left to make
   room rather than the two overlapping. */
.ps-searchpage-identifier-clear {
  position: absolute; right: 8px; top: 50%; transform: translateY(-50%);
  width: 18px; height: 18px; border-radius: 50%; border: none;
  background: rgba(255,255,255,0.08); color: #94a3b8;
  font-size: 14px; line-height: 1; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  padding: 0;
}
.ps-searchpage-identifier-clear:hover { background: rgba(255,255,255,0.16); color: #e2e8f0; }
.ps-searchpage-identifier-clear + .ps-searchpage-identifier-badge { right: 30px; }
/* margin-top added - real, per direct feedback: with no gap between
   the form's own stacked field groups, a label sat visually touching
   whatever field came before it, reading as cramped. margin-bottom
   stays small/unchanged - that tight coupling between a label and its
   OWN input below it is correct and intentional; the fix is real
   separation from the PRECEDING field, not from this label's own
   input. */
.ps-searchpage-section-mb4 { margin-top: 12px; margin-bottom: 4px; }
.ps-searchpage-section-mb6 { margin-bottom: 6px; }
.ps-searchpage-section-mb8 { margin-bottom: 8px; }
.ps-searchpage-mini-label {
  font-size: 10px; color: #64748b; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 4px;
}
.ps-searchpage-mini-label--soft { color: #94a3b8; }
.ps-searchpage-pill-row { display: flex; flex-wrap: wrap; gap: 3px; }
.ps-searchpage-mini-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.ps-searchpage-mini-field-label { font-size: 9px; color: #94a3b8; margin-bottom: 2px; }
.ps-searchpage-mini-field-label--dim { color: #94a3b8; }
.ps-searchpage-status-priority-row { display: flex; flex-direction: column; gap: 4px; }
.ps-searchpage-label-pair-row { display: flex; align-items: center; gap: 6px; }
.ps-searchpage-vdivider { width: 1px; height: 10px; background: rgba(255,255,255,0.1); }
.ps-searchpage-vdivider--stretch { width: 1px; align-self: stretch; background: rgba(255,255,255,0.1); margin: 0 2px; }
.ps-searchpage-header-row { display: flex; align-items: center; gap: 6px; margin-bottom: 4px; }

.ps-searchpage-input-row { display: flex; gap: 4px; }
.ps-searchpage-pill-row--mt4 { margin-top: 4px; display: flex; flex-wrap: wrap; gap: 3px; }
.ps-searchpage-add-btn {
  border: none; border-radius: 6px; padding: 0 8px;
  background: #0891B2; color: #e5e7eb; font-size: 12px; font-weight: 700;
  cursor: pointer; flex-shrink: 0;
}
