/* Real, per direct request for a sales-demo mode — always visibly
   labeled, never blending in with real board content. */
.ps-orboard-header-actions { display: flex; align-items: center; gap: 12px; }
.ps-orboard-demo-badge {
  font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em;
  padding: 4px 10px; border-radius: 10px; background: rgba(96, 165, 250, 0.2); color: #60a5fa;
}

.ps-orboard-empty { text-align: center; padding: 80px; color: #6b7280; font-size: 20px; }

/* Rows — full-width, one per active specimen, replacing the earlier
   card grid per direct instruction. */
.ps-orboard-row-list { display: flex; flex-direction: column; gap: 10px; }
.ps-orboard-row {
  display: grid;
  grid-template-columns: 1.4fr 0.6fr 1.4fr 0.9fr;
  align-items: center;
  gap: 16px;
  background: #111827;
  border-radius: 12px;
  padding: 16px 20px;
  border: 3px solid transparent;
}
/* State 1 — In Progress. Border/timer color keyed to real TAT status. */
.ps-orboard-row--normal { border-color: #22C55E; }
.ps-orboard-row--warning { border-color: #F59E0B; }
.ps-orboard-row--overdue { border-color: #EF4444; }
/* State 2 — Completed, awaiting dismissal. Solid high-contrast green
   across the entire row, per spec (dark-mode stop #1E7E34). */
.ps-orboard-row--completed { background: #1E7E34; border-color: #1E7E34; }
/* Real, per spec's own "flashes brightly between High-Contrast Green
   and White 3 times... before settling into a solid green state" —
   fires once on the real transition moment (see the page's own
   onAnimationEnd handler), never replays on a later poll. */
.ps-orboard-row--flashing { animation: ps-orboard-completion-flash 1.8s steps(1, end) 1; }
/* State 3 — Dismissal Pending (modal active). Dimmed 50% overlay on
   the completed row while the confirm modal is open. */
.ps-orboard-dismiss-pending-overlay .ps-orboard-row--completed { opacity: 1; }
/* State 4 — Dismissed. Slides left and fades out over 400ms before
   the row genuinely leaves the board. */
.ps-orboard-row--dismissing { animation: ps-orboard-slide-out 0.4s ease-out forwards; }

.ps-orboard-row-context { min-width: 0; }
.ps-orboard-row-patient { font-size: 22px; font-weight: 700; }
.ps-orboard-row-meta { color: #9ca3af; font-size: 14px; margin-top: 2px; }
.ps-orboard-row--completed .ps-orboard-row-meta { color: #D4EDDA; }

.ps-orboard-row-timer { font-size: 40px; font-weight: 800; font-variant-numeric: tabular-nums; text-align: center; }
.ps-orboard-row--normal .ps-orboard-row-timer { color: #22C55E; }
.ps-orboard-row--warning .ps-orboard-row-timer { color: #F59E0B; }
.ps-orboard-row--overdue .ps-orboard-row-timer { color: #EF4444; animation: ps-orboard-timer-flash-red 1s step-start infinite; }
.ps-orboard-row--completed .ps-orboard-row-timer { color: #ffffff; }

.ps-orboard-row-diagnostic { min-width: 0; font-size: 15px; }
.ps-orboard-row-step { color: #9ca3af; }
/* Real, per spec's own "large, bold font" for the rendered preliminary
   diagnosis text — white on the solid green row for max contrast. */
.ps-orboard-row-preliminary { color: #ffffff; font-weight: 700; font-size: 18px; }

.ps-orboard-row-actions { display: flex; flex-direction: column; gap: 8px; }
.ps-orboard-inprogress-btn {
  min-height: 44px; padding: 10px; font-size: 14px; font-weight: 700;
  background: #1f2937; color: #6b7280; border: 1px solid #374151; border-radius: 10px; cursor: not-allowed;
}
.ps-orboard-verbal-report-link {
  background: none; border: none; color: #60a5fa; font-size: 13px; cursor: pointer; padding: 2px 0;
}
/* Real, per spec's own two hard requirements: minimum 64x64 touch
   target for gloved/wall-mounted use, and a continuous soft pulse
   (opacity 80%-100%) to draw the eye without any audio. */
.ps-orboard-dismiss-btn {
  min-height: 64px; min-width: 64px; padding: 14px; font-size: 16px; font-weight: 700;
  background: #ffffff; color: #0F3D1A; border: none; border-radius: 10px; cursor: pointer;
  animation: ps-orboard-dismiss-pulse 2s ease-in-out infinite;
}

/* ── Keyframes — visual-only signaling, no audio anywhere on this page ── */
@keyframes ps-orboard-completion-flash {
  0%, 16.66%, 33.33% { background: #1E7E34; }
  8.33%, 25%, 41.66% { background: #ffffff; }
  50%, 100% { background: #1E7E34; }
}
@keyframes ps-orboard-dismiss-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.8; }
}
@keyframes ps-orboard-timer-flash-red {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0.55; }
}
@keyframes ps-orboard-slide-out {
  0% { transform: translateX(0); opacity: 1; }
  100% { transform: translateX(-40px); opacity: 0; }
}

