/* PathScribeEditor.tsx — pse- prefix (section 27 — rich-text editor
   toolbar and its dropdown/modal sub-components: FindReplacePanel,
   InsertTableModal, MacroModal, SpacingDropdown, ColorPicker,
   BorderDropdown, tab-width menu). The dropdown-anchored panels share a
   common `.pse-dropdown-panel` base for position/border/shadow, with a
   per-panel width override. The tab-width menu keeps its colors driven by
   the editor's light/dark EditorThemeContext via CSS custom properties,
   the same pattern used by FlagRow.tsx's severity badges, since (unlike
   the rest of this file) its background/text really is per-theme dynamic. */
.pse-loading-wrap { border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden; background: white; display: flex; align-items: center; justify-content: center; }
.pse-loading-text { font-size: 12px; color: #94a3b8; }

.pse-toolbar-swatch-icon { display: flex; flex-direction: column; align-items: center; line-height: 1; }
.pse-toolbar-swatch-bar { width: 14px; height: 3px; border-radius: 1px; margin-top: 1px; }
.pse-toolbar-swatch-bar--red { background: #dc2626; }
.pse-toolbar-swatch-bar--yellow { background: #fde047; }
.pse-toolbar-icon-badge { position: relative; display: inline-flex; }
.pse-toolbar-macro-label { font-size: 11px; font-weight: 700; }

.pse-tabwidth-menu { position: absolute; top: 32px; left: 0; background: var(--pse-tw-bg, white); border: 1px solid var(--pse-tw-border, #e2e8f0); border-radius: 8px; padding: 6px; box-shadow: var(--pse-tw-shadow, 0 8px 24px rgba(0,0,0,0.12)); z-index: 50; min-width: 90px; }
.pse-tabwidth-item { display: block; width: 100%; padding: 6px 10px; text-align: left; background: var(--pse-tw-item-bg, transparent); color: var(--pse-tw-item-color, #1e293b); border: none; border-radius: 5px; font-size: 12px; cursor: pointer; font-weight: 500; }

.pse-dropdown-panel { position: absolute; top: 32px; left: 0; background: white; border: 1px solid #e2e8f0; border-radius: 8px; padding: 10px; box-shadow: 0 8px 24px rgba(0,0,0,0.12); z-index: 50; }
.pse-dropdown-close { background: none; border: none; color: #94a3b8; font-size: 13px; cursor: pointer; padding: 2px 6px; line-height: 1; }
.pse-dropdown-close:hover { color: #ef4444; }
.pse-dropdown-input { display: block; width: 200px; padding: 6px 8px; border: 1px solid #e2e8f0; border-radius: 5px; font-size: 12px; margin-bottom: 6px; box-sizing: border-box; }
.pse-dropdown-section-label { font-size: 11px; font-weight: 700; color: #64748b; text-transform: uppercase; letter-spacing: 0.03em; padding: 4px 6px; }
.pse-dropdown-section-label--nopad { padding-top: 0; }
.pse-dropdown-item { display: block; width: 100%; text-align: left; padding: 6px 8px; font-size: 12px; color: #1e293b; background: none; border: none; border-radius: 5px; cursor: pointer; }
.pse-dropdown-item:hover { background: #f1f5f9; }
.pse-dropdown-item--withicon { display: flex; align-items: center; gap: 8px; }

.pse-findreplace-panel { width: 220px; }
.pse-findreplace-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; }
.pse-findreplace-tabs { display: flex; gap: 4px; }
.pse-findreplace-tab { padding: 3px 10px; font-size: 11px; font-weight: 600; color: #64748b; background: none; border: none; border-radius: 5px; cursor: pointer; }
.pse-findreplace-tab--active { background: #0891B2; color: white; }
.pse-findreplace-matchcount { font-size: 11px; color: #64748b; margin-bottom: 6px; }
.pse-findreplace-actions { display: flex; gap: 6px; }
.pse-btn-primary-block { flex: 1; padding: 6px 8px; font-size: 12px; font-weight: 600; color: white; background: #0891B2; border: none; border-radius: 5px; cursor: pointer; }
.pse-btn-secondary-block { flex: 1; padding: 6px 8px; font-size: 12px; font-weight: 600; color: #1e293b; background: #f1f5f9; border: none; border-radius: 5px; cursor: pointer; }

