/* ── TemplateRenderer.tsx — batch 111 additions ──────────────────────────
   This file previously had almost no dedicated CSS class family — nearly
   everything was raw inline style={{}} objects (nav bar, breadcrumb,
   lifecycle action bar, template sections/fields, all three modals), reused
   only .ps-overlay/.ps-modal-dark/.ps-conf-btn-secondary/.ps-btn-danger-solid
   from elsewhere. New ps-tmplr-* family below carries all the STATIC
   styling; genuinely per-item/per-state dynamic colors (lifecycle-state
   background/color/border, selected-option border/background) stay inline,
   same convention used throughout this sweep. JS onMouseEnter/onMouseLeave
   hover-color-swap handlers (back button, breadcrumb links, transition
   buttons, reset button, confirm button, leave-anyway button) are replaced
   by real CSS :hover rules here. */
.ps-tmplr-page {
  min-height: 100vh;
  background: #0f172a;
  background-image: linear-gradient(to bottom, #0f172a 0%, #020617 100%);
  color: #f1f5f9;
  font-family: 'Inter', sans-serif;
}

.ps-tmplr-nav {
  padding: 12px 40px;
  background: rgba(0,0,0,0.4);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
}
.ps-tmplr-nav-left  { display: flex; align-items: center; gap: 16px; }
.ps-tmplr-nav-right { display: flex; align-items: center; gap: 10px; }

.ps-tmplr-back-btn {
  padding: 7px 14px; border-radius: 7px;
  border: 1px solid #334155; background: rgba(255,255,255,0.04);
  color: #94a3b8; cursor: pointer; font-size: 13px; font-weight: 500;
  transition: color 0.15s;
}
.ps-tmplr-back-btn:hover { color: #f1f5f9; }

.ps-tmplr-breadcrumb {
  font-size: 13px; color: #475569;
  display: flex; align-items: center; gap: 6px;
}
.ps-tmplr-breadcrumb-link {
  cursor: pointer; color: #64748b; transition: color 0.15s;
}
.ps-tmplr-breadcrumb-link:hover { color: #0891B2; }
.ps-tmplr-breadcrumb-sep     { color: #334155; }
.ps-tmplr-breadcrumb-current { color: #f1f5f9; font-weight: 600; }

.ps-tmplr-unsaved-indicator { font-size: 12px; color: #f59e0b; font-weight: 500; }

/* Per-state colours (Batch 328, replacing TemplateRenderer's inline styles). */
.ps-tmplr-state--draft         { --tmplr-bg: rgba(100,116,139,0.15); --tmplr-fg: #94a3b8; --tmplr-border: rgba(100,116,139,0.3); }
.ps-tmplr-state--in_review     { --tmplr-bg: rgba(245,158,11,0.15);  --tmplr-fg: #fbbf24; --tmplr-border: rgba(245,158,11,0.3); }
.ps-tmplr-state--needs_changes { --tmplr-bg: rgba(239,68,68,0.15);   --tmplr-fg: #f87171; --tmplr-border: rgba(239,68,68,0.3); }
.ps-tmplr-state--approved      { --tmplr-bg: rgba(16,185,129,0.15);  --tmplr-fg: #10B981; --tmplr-border: rgba(16,185,129,0.3); }
.ps-tmplr-state--published     { --tmplr-bg: rgba(8,145,178,0.15);   --tmplr-fg: #38bdf8; --tmplr-border: rgba(8,145,178,0.3); }

.ps-tmplr-lifecycle-badge {
  font-size: 12px; font-weight: 700;
  padding: 4px 14px; border-radius: 99px;
  text-transform: capitalize; white-space: nowrap;
  background: var(--tmplr-bg); color: var(--tmplr-fg); border: 1px solid var(--tmplr-border);
}

.ps-tmplr-coding-badges { display: inline-flex; gap: 4px; margin-left: 8px; }
