   LeftReportPanel.tsx — the read-only, case-level "Full Patient
   Report" summary panel.
   ============================================================ */

@keyframes ps-highlight-pop {
  0%   { background: rgba(251,191,36,0.9); box-shadow: 0 0 0 4px rgba(251,191,36,0.7); }
  100% { background: rgba(251,191,36,0.45); box-shadow: 0 0 0 2px rgba(251,191,36,0.5); }
}
@keyframes ps-review-waiting-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(139,92,246,0.55); }
  50%      { box-shadow: 0 0 0 6px rgba(139,92,246,0); }
}

.ps-leftreport-panel {
  width: 100%;
  height: 100%;
  background: #111827;
  border-right: 1px solid rgba(8,145,178,0.3);
  overflow-y: auto;
  padding: 16px 32px 32px;
  box-sizing: border-box;
  position: relative;
}
.ps-leftreport-panel--watermark { background-image: var(--ps-watermark-image); background-repeat: repeat; background-attachment: local; }

.ps-leftreport-highlight-mark {
  background: rgba(251,191,36,0.45);
  color: #fde68a;
  border-radius: 3px;
  padding: 1px 4px;
  box-shadow: 0 0 0 2px rgba(251,191,36,0.5);
  animation: ps-highlight-pop 0.5s ease;
