.ps-leftreport-review-badge { background: #8B5CF6; color: #fff; border-radius: 10px; padding: 0 6px; height: 16px; font-size: 9px; font-weight: 800; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.ps-leftreport-unread-badge { background: #F59E0B; color: #000; border-radius: 50%; width: 16px; height: 16px; font-size: 9px; font-weight: 800; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }

.ps-leftreport-lis-notice { display: flex; align-items: center; gap: 6px; padding: 5px 10px; background: rgba(8,145,178,0.08); border: 1px solid rgba(8,145,178,0.2); border-radius: 6px; margin-bottom: 16px; font-size: 11px; color: #38bdf8; }

.ps-leftreport-empty-text { color: #94a3b8; font-size: 14px; }

.ps-leftreport-section       { margin-bottom: 28px; border-left: 3px solid rgba(8,145,178,0.4); padding-left: 14px; }
