  border-color: var(--ps-conf-border-active);
  border-radius: 10px 10px 0 0;
}
.ps-activeprotocols-row--open:hover { background: var(--ps-conf-surface-2); border-color: var(--ps-conf-border-active); }

.ps-activeprotocols-cat-bar { width: 3px; height: 36px; border-radius: 2px; flex-shrink: 0; }

.ps-activeprotocols-info { flex: 1; min-width: 0; }
.ps-activeprotocols-name { font-size: 14px; font-weight: 600; color: #f1f5f9; margin-bottom: 4px; }
.ps-activeprotocols-meta { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.ps-activeprotocols-version { font-size: 11px; color: #64748b; font-family: monospace; }
.ps-activeprotocols-dot { color: #334155; }
.ps-activeprotocols-source-badge { font-size: 10px; font-weight: 700; font-family: monospace; padding: 1px 7px; border-radius: 4px; }
