.ps-activeprotocols-stat-label { font-size: 10px; color: #475569; margin-top: 3px; text-transform: uppercase; letter-spacing: 0.06em; }
.ps-activeprotocols-coverage-row { display: flex; gap: 16px; flex: 1; min-width: 220px; align-items: flex-end; }

.ps-activeprotocols-lifecycle { display: flex; align-items: center; gap: 6px; margin-bottom: 16px; }
