.ps-activeprotocols-header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 16px; }
.ps-activeprotocols-title { font-size: 15px; font-weight: 700; color: #f1f5f9; margin-bottom: 4px; }
