.ps-activeprotocols-group { margin-bottom: 24px; }
.ps-activeprotocols-group-header { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.ps-activeprotocols-group-label { font-size: 10px; font-weight: 800; letter-spacing: 0.1em; }
.ps-activeprotocols-group-divider { flex: 1; height: 1px; background: #1e293b; }
