  font-size: 18px; line-height: 1; padding: 4px 9px; flex-shrink: 0;
  transition: all 0.15s;
}
.ps-lookup-close-btn:hover { color: #f1f5f9; border-color: rgba(255,255,255,0.3); }

.ps-lookup-content { flex: 1; min-height: 0; overflow-y: auto; }

.ps-lookup-footer {
  padding: 12px 24px;
  border-top: 1px solid rgba(255,255,255,0.08);
  flex-shrink: 0;
  display: flex; justify-content: flex-end;
