.ps-editor-content { padding: 20px 24px; min-height: var(--pse-min-height, 400px); outline: none; font-size: 12pt; line-height: 1.8; color: var(--pse-content-text, #1e293b); font-family: var(--pse-font-family, Arial, sans-serif); }
