/* Audit Log → Interfaces → Outbound Dispatches (PS-86, Batch 318). */
.ps-auditlog-thead--dispatch,
.ps-auditlog-row--dispatch { grid-template-columns: 165px minmax(160px, 1fr) 110px 120px 130px minmax(140px, 1fr) 100px; }
button.ps-auditlog-row--dispatch {
  width: 100%; text-align: left; background: transparent; border: none;
  border-bottom: 1px solid rgba(255,255,255,0.06); color: inherit; font: inherit; cursor: pointer;
}
button.ps-auditlog-row--dispatch:hover,
button.ps-auditlog-row--dispatch:focus-visible { background: rgba(255,255,255,0.04); outline: none; }
.ps-dispatch-mono { font-family: monospace; font-size: 12px; overflow-wrap: anywhere; }
.ps-dispatch-status { padding: 3px 8px; border-radius: 12px; font-size: 11px; font-weight: 700; white-space: nowrap; }
.ps-dispatch-status--delivered { background: rgba(16,185,129,0.12); color: #10B981; }
.ps-dispatch-status--failed    { background: rgba(239,68,68,0.12);  color: #ef4444; }
.ps-dispatch-status--recorded  { background: rgba(148,163,184,0.12); color: #94a3b8; }
.ps-dispatch-attempts { margin-left: 8px; font-size: 12px; color: #94a3b8; }
.ps-dispatch-meta { display: grid; grid-template-columns: max-content 1fr; gap: 6px 16px; margin: 0 0 12px; font-size: 13px; }
.ps-dispatch-meta dt { color: #94a3b8; font-weight: 600; }
.ps-dispatch-meta dd { margin: 0; color: #e2e8f0; }
.ps-dispatch-json {
  margin-top: 8px; padding: 12px; max-height: 50vh; overflow: auto;
  background: rgba(0,0,0,0.25); border: 1px solid rgba(255,255,255,0.08); border-radius: 8px;
