.ps-dispatch-json-leaf { padding-left: 14px; }
.ps-dispatch-json-key { color: #8AB4F8; }
.ps-dispatch-json-string { color: #81C995; overflow-wrap: anywhere; }
.ps-dispatch-json-literal { color: #fbbf24; }
.ps-dispatch-json-null { color: #94a3b8; font-style: italic; }
.ps-dispatch-json-punct { color: #94a3b8; }
.ps-dispatch-json-size { margin: 0 4px; font-size: 11px; color: #64748b; }

/* ── Assist LIS Polling (PS-87, Config → System → Integrations) ── */
.ps-assist-poll-interval { max-width: 120px; min-width: 0; }
.ps-assist-poll-actions { display: flex; align-items: center; gap: 8px; margin-top: 12px; }
.ps-assist-poll-message { display: block; width: 100%; box-sizing: border-box; min-height: 140px; margin-top: 10px; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: 12px; resize: vertical; }

/* ── Code Import (PS-89, Config → System → Financial & Revenue Lookups) ── */
.ps-code-import-card { margin-bottom: 16px; }
.ps-code-import-file-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin: 8px 0 12px; }
.ps-code-import-mapping-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 4px 12px; }
.ps-code-import-actions { display: flex; align-items: center; gap: 8px; margin-top: 12px; }
.ps-code-import-problems { max-height: 280px; overflow-y: auto; }
.ps-code-import-skip { display: flex; align-items: center; gap: 8px; margin-top: 10px; font-size: 13px; cursor: pointer; }

/* ── Country Signing Rules (PS-341, Config → System → Clinical Lookups) ── */
.ps-csr-banner { margin: 0 0 14px; }
.ps-csr-toolbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; }
.ps-csr-toolbar .ps-conf-label { margin: 0; }
.ps-csr-country { max-width: 320px; }
.ps-csr-list { display: flex; flex-direction: column; gap: 12px; }
.ps-csr-card { padding: 12px 14px; border-radius: 10px; border: 1px solid color-mix(in srgb, var(--ps-hue) 30%, transparent); background: color-mix(in srgb, var(--ps-hue) 5%, transparent); }
.ps-csr-card--changed { border-color: #f59e0b; }
.ps-csr-card--muted { opacity: 0.6; }
.ps-csr-card__head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 8px; }
.ps-csr-card__dot { width: 10px; height: 10px; border-radius: 50%; background: var(--ps-hue); flex: none; }
.ps-csr-card__type { font-weight: 600; font-size: 14px; }
.ps-csr-badge { font-size: 11px; padding: 2px 8px; border-radius: 999px; border: 1px solid #374151; color: #9ca3af; }
.ps-csr-badge--global { border-color: rgba(96,165,250,0.4); color: #60a5fa; }
.ps-csr-badge--offered { border-color: rgba(45,212,191,0.4); color: #2dd4bf; }
.ps-csr-badge--notOffered { border-color: #4b5563; color: #6b7280; }
.ps-csr-badge--changed { border-color: rgba(245,158,11,0.5); color: #f59e0b; }
.ps-csr-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 4px 12px; }
.ps-csr-note { min-height: 44px; resize: vertical; font-family: inherit; }
.ps-csr-savebar { position: sticky; bottom: 0; margin-top: 16px; z-index: 2; padding: 12px 16px; background: var(--ps-conf-bg); box-shadow: 0 -6px 16px rgba(0,0,0,0.45); }
.ps-csr-savebar__actions { display: flex; align-items: center; justify-content: flex-end; gap: 8px; flex-wrap: wrap; }
.ps-csr-savebar__actions .ps-conf-hint { margin-right: auto; }

/* ── Live-update status badge (PS-262, batch 342): components/LiveUpdates/LiveStatusBadge.tsx.
   Visual only; the dot's colour and the label say whether the screen is receiving
   live updates, only local ones, or is reconnecting / offline and polling. ── */
.ps-live-badge {
  --ps-hue: #64748b;
  display: inline-flex; align-items: center; gap: 6px;
  padding: 3px 10px; border-radius: 999px;
  font-size: 12px; font-weight: 600; white-space: nowrap; cursor: default;
  color: inherit;
  background: color-mix(in srgb, var(--ps-hue) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--ps-hue) 45%, transparent);
}
.ps-live-badge__dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ps-hue); flex-shrink: 0; }
.ps-live-badge--live { --ps-hue: #22c55e; }
.ps-live-badge--local { --ps-hue: #38bdf8; }
.ps-live-badge--connecting, .ps-live-badge--reconnecting { --ps-hue: #f59e0b; }
.ps-live-badge--offline { --ps-hue: #ef4444; }
.ps-live-badge--connecting .ps-live-badge__dot,
.ps-live-badge--reconnecting .ps-live-badge__dot { animation: ps-live-badge-pulse 1.2s ease-in-out infinite; }
@keyframes ps-live-badge-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }
@media (prefers-reduced-motion: reduce) {
  .ps-live-badge--connecting .ps-live-badge__dot,
  .ps-live-badge--reconnecting .ps-live-badge__dot { animation: none; }
}
/* On the OR wall display the badge is read from across the room. */
.ps-orboard-live-badge { font-size: 15px; padding: 5px 14px; }
.ps-orboard-live-badge .ps-live-badge__dot { width: 11px; height: 11px; }

/* ── PathScribe Agent print progress (PS-52, batch 346): components/Printing/AgentPrintStatus.tsx.
   A small pill at the bottom left while this tab's labels are sending, queued or printing.
   The region is always present (so screen readers hear the change) and takes no space when empty. ── */
.ps-agent-print-status-region { pointer-events: none; }
.ps-agent-print-status {
  --ps-hue: #38bdf8;
  display: inline-flex; align-items: center; gap: 8px;
  padding: 6px 14px; border-radius: 999px;
  font-size: var(--ps-text-md); font-weight: 600; color: var(--ps-text);
  background: color-mix(in srgb, var(--ps-hue) 14%, var(--ps-surface));
  border: 1px solid color-mix(in srgb, var(--ps-hue) 50%, transparent);
  box-shadow: 0 6px 18px rgba(0,0,0,0.35);
}
.ps-agent-print-status--queued { --ps-hue: #f59e0b; }
.ps-agent-print-status--printing { --ps-hue: #22c55e; }
.ps-agent-print-status-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ps-hue); flex-shrink: 0; }
.ps-agent-print-status--sending .ps-agent-print-status-dot,
.ps-agent-print-status--printing .ps-agent-print-status-dot { animation: ps-live-badge-pulse 1.2s ease-in-out infinite; }
.ps-agent-print-status-more { font-weight: 400; color: var(--ps-text-muted); }
@media (prefers-reduced-motion: reduce) {
  .ps-agent-print-status-dot { animation: none !important; }
}

/* Printer profile editor: the PathScribe Agent port hint (batch 346). */
.ps-printer-agent-port-hint { margin: 4px 0 0; font-size: var(--ps-text-xs); color: var(--ps-text-muted); }
.ps-printer-agent-port-hint--error { color: #f87171; }

/* ── Print feedback column (batch 347): the network print jobs above the agent status pill,
   bottom left, from App.tsx. Only the jobs' buttons take clicks. ── */
.ps-print-feedback {
  position: fixed; left: 16px; bottom: 16px; z-index: 9500;
  display: flex; flex-direction: column; align-items: flex-start; gap: 8px;
  max-width: min(640px, calc(100vw - 32px));
  pointer-events: none;
}
.ps-netprint-jobs { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; }
.ps-netprint-job {
  --ps-hue: #38bdf8;
  display: flex; align-items: center; flex-wrap: wrap; gap: 8px;
  padding: 8px 12px; border-radius: var(--ps-radius-md);
  font-size: var(--ps-text-md); color: var(--ps-text);
  background: color-mix(in srgb, var(--ps-hue) 14%, var(--ps-surface));
  border: 1px solid color-mix(in srgb, var(--ps-hue) 50%, transparent);
  box-shadow: 0 6px 18px rgba(0,0,0,0.35);
  pointer-events: auto;
}
.ps-netprint-job--noReply { --ps-hue: #f59e0b; }
.ps-netprint-job--printed { --ps-hue: #22c55e; }
.ps-netprint-job--failed { --ps-hue: #ef4444; }
.ps-netprint-job-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ps-hue); flex-shrink: 0; }
.ps-netprint-job--waiting .ps-netprint-job-dot { animation: ps-live-badge-pulse 1.2s ease-in-out infinite; }
.ps-netprint-job-text { font-weight: 600; }
.ps-netprint-job-attempt { font-size: var(--ps-text-xs); color: var(--ps-text-muted); }
.ps-netprint-job-sim,
.ps-netprint-job-actions { display: inline-flex; gap: 6px; white-space: nowrap; }
.ps-netprint-job-btn {
  font-size: var(--ps-text-sm); font-weight: 600; cursor: pointer;
  padding: 3px 10px; border-radius: var(--ps-radius-sm);
  color: var(--ps-text); background: transparent;
  border: 1px solid color-mix(in srgb, var(--ps-text-muted) 45%, transparent);
}
.ps-netprint-job-btn:hover { background: color-mix(in srgb, var(--ps-text) 8%, transparent); }
.ps-netprint-job-btn--primary { background: var(--ps-teal); border-color: var(--ps-teal); color: #fff; }
.ps-netprint-job-btn--primary:hover { background: var(--ps-teal-hover); }
.ps-netprint-job-btn--sim { border-style: dashed; color: var(--ps-text-muted); font-weight: 400; }
.ps-netprint-job-btn:focus-visible { outline: 2px solid var(--ps-teal-light); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) {
  .ps-netprint-job-dot { animation: none !important; }
}

/* Case Search: note under the identifier box (batch 349, PS-101). */
.ps-searchpage-identifier-hint { margin: 6px 2px 10px; font-size: 11px; color: var(--ps-text-muted); }
/* Batch 354: under the organisation filters — a Trust includes its sites. */
.ps-searchpage-org-hint { margin: 4px 2px 0; font-size: 11px; color: var(--ps-text-muted); }

/* Batch 353: WorklistPage.tsx's page layout (were inline styles). */
.ps-wl-page { position: relative; width: 100vw; height: var(--app-height, 100vh); font-family: 'Inter', sans-serif; display: flex; flex-direction: column; }
.ps-wl-page-content { position: relative; z-index: 10; display: flex; flex-direction: column; height: 100%; }
.ps-wl-page-main { flex: 1; min-height: 0; padding: clamp(8px,1.5vw,12px) clamp(12px,2vw,20px); display: flex; flex-direction: column; }
.ps-wl-page-main-inner { width: 100%; display: flex; flex-direction: column; flex: 1; min-height: 0; }
.ps-wl-header--page { margin-bottom: 12px; flex-shrink: 0; }

/* Batch 360: equipment service status and log (EquipmentSection, EquipmentLogModal). */
.ps-eqlog-state { display: inline-block; padding: 2px 8px; border-radius: 99px; font-size: 11px; font-weight: 700; white-space: nowrap;
  background: color-mix(in srgb, var(--eqlog-hue, #64748b) 15%, transparent); color: var(--eqlog-hue, #94a3b8);
  border: 1px solid color-mix(in srgb, var(--eqlog-hue, #64748b) 35%, transparent); }
.ps-eqlog-state--malfunction, .ps-eqlog-state--overdue { --eqlog-hue: #ef4444; }
