.ps-eqlog-alert { margin-bottom: 12px; padding: 8px 12px; border-radius: 8px; font-size: 13px; color: #fecaca;
  background: rgba(239,68,68,0.12); border: 1px solid rgba(239,68,68,0.35); }
.ps-eqlog-due { display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px; }
.ps-eqlog-due-row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: 13px; }
.ps-eqlog-due-label { min-width: 110px; font-weight: 600; color: #e2e8f0; }
.ps-eqlog-muted { font-size: 12px; color: var(--ps-text-muted, #94a3b8); }
.ps-eqlog-section-title { margin: 14px 0 8px; font-size: 12px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: #94a3b8; }
.ps-eqlog-add-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 6px 0 4px; }
.ps-eqlog-outcome { font-weight: 600; }
.ps-eqlog-outcome--pass { color: #10b981; }
.ps-eqlog-outcome--fail { color: #ef4444; }
.ps-eqlog-outcome--not_applicable { color: #94a3b8; }
/* Batch 361: a device with an open malfunction or past due, shown in red (flagged, not blocked). */
.ps-conf-tr.ps-eqlog-row--alert > td { background: color-mix(in srgb, #ef4444 8%, transparent); }
.ps-conf-tr.ps-eqlog-row--alert > td:first-child { box-shadow: inset 3px 0 0 #ef4444; }
.ps-eqlog-row--alert .ps-conf-identity-name { color: #f87171; }
.mb-instrument-select--alert { border-color: #ef4444; box-shadow: 0 0 0 1px #ef4444; }
.mb-instrument-option--alert { color: #f87171; }
.mb-instrument-alert { margin-top: 4px; font-size: 11px; font-weight: 600; color: #f87171; }

/* ── Batch 364 (PS-350): support references ─────────────────────────────── */
.ps-supportref-chip { display: inline-flex; align-items: center; gap: 4px; margin-left: 8px; padding: 1px 7px; border-radius: 999px; border: 1px dashed rgba(148,163,184,0.45); background: transparent; color: #94a3b8; font-size: 11px; font-family: inherit; cursor: pointer; vertical-align: middle; white-space: nowrap; }
.ps-supportref-chip:hover { border-color: #0891B2; color: #e2e8f0; }
