.ps-supportref-lookup-entry { display: flex; gap: 10px; flex-wrap: wrap; align-items: baseline; }
.ps-supportref-lookup-muted { color: #94a3b8; font-size: 12px; }
.erm-identifier-warning-actions .ps-conf-btn-secondary { color: #e2e8f0; border-color: rgba(226,232,240,0.4); background: rgba(15,23,42,0.4); opacity: 1; }

/* ── Batch 367 (PS-74): the last inline styles, moved here ─────────────────── */

