.ps-tpp-ruler-margin--left { width: var(--tpp-ml); }
.ps-tpp-ruler-margin--right { width: var(--tpp-mr); }
.ps-tpp-page-card { width: var(--tpp-w); min-height: var(--tpp-h); }
