.ps-tpp-page-body { padding-left: var(--tpp-ml); padding-right: var(--tpp-mr); }
.ps-tpp-page-footer { padding: 0 var(--tpp-mr) var(--tpp-mb) var(--tpp-ml); }

/* Small components (Batch 367). Hue-driven colours use --ps-hue with the same
