.ps-modal-dark--draft-recovery { width: 440px; }
.ps-modal-dark--draft-recovery-wide { width: 480px; }
.ps-lookup-item-badge { color: var(--ps-hue); background: color-mix(in srgb, var(--ps-hue) 9.4%, transparent); border: 1px solid color-mix(in srgb, var(--ps-hue) 18.8%, transparent); }
.ps-patient-id-status-dot-shape { width: var(--dot-size); height: var(--dot-size); background: var(--ps-hue); box-shadow: 0 0 4px color-mix(in srgb, var(--ps-hue) 60%, transparent); }
.ps-cytcat-chip { background: rgba(255,255,255,0.04); color: #4b5563; border: 1px solid rgba(255,255,255,0.06); }
.ps-cytcat-chip--filled { background: color-mix(in srgb, var(--ps-hue) 9.4%, transparent); color: var(--ps-hue); border-color: color-mix(in srgb, var(--ps-hue) 20%, transparent); }

/* Report preview (ReportPreviewRenderer.tsx): a template's label formatting
   arrives as --rp-<part>-* custom properties (utils/labelStyleVars.ts), set
   only for configured values. Each part has its own names so a page's
   settings don't leak into its headings; unset means the normal look. */
.rp-page { font-family: var(--rp-body-family, 'Georgia', 'Times New Roman', serif); font-size: var(--rp-body-size, inherit); font-weight: var(--rp-body-weight, inherit); text-transform: var(--rp-body-transform, inherit); text-decoration: var(--rp-body-decoration, none); }
.rp-doc-header { font-family: var(--rp-header-family, inherit); font-size: var(--rp-header-size, inherit); font-weight: var(--rp-header-weight, inherit); text-transform: var(--rp-header-transform, inherit); text-decoration: var(--rp-header-decoration, none); }
.rp-doc-footer { font-family: var(--rp-footer-family, inherit); font-size: var(--rp-footer-size, inherit); font-weight: var(--rp-footer-weight, inherit); text-transform: var(--rp-footer-transform, inherit); text-decoration: var(--rp-footer-decoration, none); }
.rp-node-section-heading { font-family: var(--rp-heading-family, inherit); font-size: var(--rp-heading-size, inherit); font-weight: var(--rp-heading-weight, inherit); text-transform: var(--rp-heading-transform, inherit); text-decoration: var(--rp-heading-decoration, none); }
.rp-node-label { font-family: var(--rp-label-family, inherit); font-size: var(--rp-label-size, inherit); font-weight: var(--rp-label-weight, inherit); text-transform: var(--rp-label-transform, inherit); text-decoration: var(--rp-label-decoration, none); }
.rp-static-label--bold { font-weight: 700; }
.rp-static-label--italic { font-style: italic; }
/* Label-style previews (Document Style, Template Assembly): unset values show
   the defaults the editors use (Arial, 10px, normal). */
.ps-docstyle__preview, .ps-tmpla-style-preview { font-family: var(--preview-family, Arial); font-size: var(--preview-size, 10px); font-weight: var(--preview-weight, 400); text-decoration: var(--preview-decoration, none); text-transform: var(--preview-transform, none); }

/* Configuration, Contribution, editor and template-builder pieces (Batch 367). */
.config-fonts-card__name { font-family: var(--font-name); }
.ps-quality-progress-fill--pct, .ps-contrib-progress-fill--pct { width: var(--bar-pct); }
.fr-row { cursor: default; }
