/* Batches, engravers, label previews, label designer (Batch 367). Alphas as
   before: 22 ≈ 13.3%, 14 ≈ 7.8%, 2e ≈ 18%. */
.ps-batch-row-status--hued { background: color-mix(in srgb, var(--ps-hue) 13.3%, transparent); color: var(--ps-hue); }
.ps-engraver-status-tile { background: color-mix(in srgb, var(--ps-hue) 7.8%, transparent); border: 1px solid color-mix(in srgb, var(--ps-hue) 18%, transparent); }
