.ps-embedding-cassette-module-dot--dim, .ps-microtomy-label-preview-barcode span.ps-microtomy-label-module--dim { opacity: 0.15; }
.ps-designer-canvas { width: var(--canvas-w); height: var(--canvas-h); }
.ps-designer-field { left: var(--field-x); top: var(--field-y); width: var(--field-w); height: var(--field-h); font-size: var(--field-font); }

/* Report page pieces (Batch 367). */
.acd-ctx-menu { left: var(--ctx-x); top: var(--ctx-y); }
.acd-ai-panel-chevron { transform: rotate(0deg); }
