.ps-dht-badge { background: color-mix(in srgb, var(--ps-hue) 13.3%, transparent); color: var(--ps-hue); }
.ps-dht-entry { border-left-color: var(--ps-hue); }
.ps-seq-progress-fill, .ps-ai-review-progress-fill { width: var(--bar-pct); }
.ps-matrixblock-core-grid { grid-template-columns: repeat(var(--mb-cols), 1fr); max-width: calc(var(--mb-cols) * 96px); }
.ps-proto-change-confidence { color: var(--ps-hue); border-color: color-mix(in srgb, var(--ps-hue) 26.7%, transparent); background: color-mix(in srgb, var(--ps-hue) 9.4%, transparent); }

/* Facility editor tabs (Batch 367; was an inline tabStyle()). */
.ps-fem-tab { padding: 8px 16px; font-size: 13px; font-weight: 600; cursor: pointer; border: none; background: transparent; border-bottom: 2px solid transparent; color: #64748b; }
.ps-fem-tab--active { border-bottom-color: #0891b2; color: #0891b2; }

/* Comment modal drag position; bottom action bar buttons (Batch 367). */
.ps-cmnt-modal { position: relative; }
.ps-cmnt-modal--positioned { position: fixed; left: calc(50% + var(--cmnt-x)); top: calc(50% + var(--cmnt-y)); transform: translate(-50%, -50%); }
.ps-bab-action-btn { padding: 6px 11px; border-radius: 7px; font-weight: 700; font-size: 12px; cursor: pointer; white-space: nowrap; transition: all 0.15s ease; border: 1.5px solid var(--ps-hue); background: transparent; color: var(--ps-hue); opacity: 1; display: flex; align-items: center; gap: 5px; transform: translateY(0); box-shadow: none; line-height: 1.2; height: 32px; box-sizing: border-box; }
.ps-bab-action-btn--solid { background: var(--ps-hue); color: white; }
.ps-bab-action-btn:hover:not(:disabled) { transform: translateY(1px); box-shadow: 0 2px 8px color-mix(in srgb, var(--ps-hue) 26.7%, transparent); }
.ps-bab-action-btn--outline:hover:not(:disabled) { background: color-mix(in srgb, var(--ps-hue) 13.3%, transparent); }
