.ps-ctm-hued { --badge-bg: color-mix(in srgb, var(--ps-hue) 9.4%, transparent); --badge-border: color-mix(in srgb, var(--ps-hue) 20%, transparent); --badge-border-strong: color-mix(in srgb, var(--ps-hue) 40%, transparent); --badge-color: var(--ps-hue); }
.ps-status-badge--hued { --status-bg: color-mix(in srgb, var(--ps-hue) 9.4%, transparent); --status-color: var(--ps-hue); --status-border: color-mix(in srgb, var(--ps-hue) 20%, transparent); }
/* Tints that used to be hex strings with an alpha suffix built in JSX
   (Batch 367): 0d ≈ 5.1%, 12 ≈ 7.1%, 18 ≈ 9.4%, 2e ≈ 18%, 40 ≈ 25.1%, 55 ≈ 33.3%, 66 = 40%. */
.vtb-btn { --vtb-bg: color-mix(in srgb, var(--vtb-color) 9.4%, transparent); --vtb-border: var(--vtb-color); }
