.ps-wl-filter-tile--hued { --tile-bg: color-mix(in srgb, var(--ps-hue) 5.1%, transparent); --tile-border: color-mix(in srgb, var(--ps-hue) 18%, transparent); --tile-shadow: none; }
.ps-wl-filter-tile--hued-active { --tile-bg: color-mix(in srgb, var(--ps-hue) 18%, transparent); --tile-border: var(--ps-hue); --tile-shadow: 0 0 12px color-mix(in srgb, var(--ps-hue) 40%, transparent); }
.eca-status-badge { --eca-status-border: color-mix(in srgb, var(--eca-status-color) 33.3%, transparent); --eca-status-bg: color-mix(in srgb, var(--eca-status-color) 9.4%, transparent); }
.ps-home-card { --card-accent-dim: color-mix(in srgb, var(--card-accent) 25.1%, transparent); }

/* ── Batch 368 (PS-353): report change history (ChangeHistoryModal.tsx) ──── */
.ps-chghist-filters { display: flex; flex-wrap: wrap; gap: 6px; margin: 4px 0 14px; }
.ps-chghist-filter { padding: 4px 10px; border-radius: 99px; border: 1px solid rgba(148,163,184,0.35); background: transparent; color: #94a3b8; font-size: 12px; font-weight: 600; cursor: pointer; }
