.ps-chghist-area--synoptic { background: rgba(8,145,178,0.18); color: #67e8f9; }
.ps-chghist-area--narrative { background: rgba(168,85,247,0.18); color: #d8b4fe; }
.ps-chghist-area--codes { background: rgba(245,158,11,0.18); color: #fcd34d; }
.ps-chghist-area--specimens { background: rgba(16,185,129,0.18); color: #6ee7b7; }
.ps-chghist-path { color: #cbd5e1; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
.ps-chghist-kind { font-size: 11px; font-weight: 700; }
.ps-chghist-kind--added { color: #34d399; }
.ps-chghist-kind--removed { color: #f87171; }
.ps-chghist-values { display: flex; flex-wrap: wrap; gap: 8px; align-items: baseline; font-size: 13px; }
.ps-chghist-before { color: #fca5a5; text-decoration: line-through; text-decoration-color: rgba(252,165,165,0.6); }
.ps-chghist-after { color: #86efac; }
.ps-chghist-arrow { color: #64748b; }
.ps-chghist-none { color: #64748b; font-style: italic; }
