.ps-chghist-diff { font-size: 13px; line-height: 1.6; color: #e2e8f0; white-space: pre-wrap; }
.ps-chghist-del { background: rgba(239,68,68,0.18); color: #fca5a5; text-decoration: line-through; }
.ps-chghist-ins { background: rgba(34,197,94,0.18); color: #86efac; text-decoration: none; }

/* ── Batch 372: Support access (Configuration → System → Support Access) ── */
.ps-supacc { display: flex; flex-direction: column; gap: 16px; }
